//! Small helpers that reproduce the Java / Jackson / commons-lang / commons-beanutils
//! behaviour the original SHOGun-Core relies on (number formatting, string
//! to value conversion of the `Map<String, Object>` appearance properties,
//! and the coercion of filter request parameters).

use serde_json::Value;

/// `java.lang.Double.toString(double)`.
pub fn java_double(d: f64) -> String {
    if d.is_nan() {
        return "NaN".to_string();
    }
    if d.is_infinite() {
        return if d > 0.0 { "Infinity" } else { "-Infinity" }.to_string();
    }
    if d == 0.0 {
        return if d.is_sign_negative() { "-0.0" } else { "0.0" }.to_string();
    }
    let abs = d.abs();
    if (1e-3..1e7).contains(&abs) {
        let s = format!("{}", d);
        if s.contains('.') {
            s
        } else {
            format!("{}.0", s)
        }
    } else {
        let s = format!("{:e}", d);
        let (mantissa, exponent) = s.split_once('e').unwrap_or((&s, "0"));
        let mantissa = if mantissa.contains('.') {
            mantissa.to_string()
        } else {
            format!("{}.0", mantissa)
        };
        format!("{}E{}", mantissa, exponent)
    }
}

/// `org.apache.commons.lang3.math.NumberUtils.isParsable`.
pub fn is_parsable(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    if s.ends_with('.') {
        return false;
    }
    let (body, start) = if let Some(rest) = s.strip_prefix('-') {
        if rest.is_empty() {
            return false;
        }
        (rest, 0)
    } else {
        (s, 0)
    };
    let _ = start;
    let mut points = 0;
    for ch in body.chars() {
        if ch == '.' {
            points += 1;
            if points > 1 {
                return false;
            }
        } else if !ch.is_ascii_digit() {
            return false;
        }
    }
    true
}

/// `NumberUtils.isDigits`.
fn is_digits(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
}

/// Converts a string stored in `LAYERAPPEARANCES_PROPERTIES.VALUE` back to the
/// best matching value, as `PropertyValueConverter.convertToEntityAttribute` does.
pub fn property_from_db(s: &str) -> Value {
    if s.eq_ignore_ascii_case("true") {
        return Value::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return Value::Bool(false);
    }
    if is_parsable(s) {
        if is_digits(s) || (s.starts_with('-') && is_digits(&s[1..])) {
            if let Ok(v) = s.parse::<i64>() {
                return Value::from(v);
            }
        }
        if let Ok(d) = s.parse::<f64>() {
            return serde_json::Number::from_f64(d)
                .map(Value::Number)
                .unwrap_or(Value::Null);
        }
    }
    Value::String(s.to_string())
}

/// `Object.toString()` of the value a Jackson `Map<String, Object>` holds, as
/// `PropertyValueConverter.convertToDatabaseColumn` stores it. Returns `None`
/// for a null value (the original fails with a NullPointerException then).
pub fn property_to_db(v: &Value) -> Option<String> {
    match v {
        Value::Null => None,
        Value::Bool(b) => Some(if *b { "true" } else { "false" }.to_string()),
        Value::String(s) => Some(s.clone()),
        Value::Number(n) => {
            if n.is_i64() || n.is_u64() {
                Some(n.to_string())
            } else {
                Some(java_double(n.as_f64().unwrap_or(0.0)))
            }
        }
        Value::Array(items) => {
            let parts: Vec<String> = items
                .iter()
                .map(|x| property_to_db(x).unwrap_or_else(|| "null".to_string()))
                .collect();
            Some(format!("[{}]", parts.join(", ")))
        }
        Value::Object(map) => {
            let parts: Vec<String> = map
                .iter()
                .map(|(k, x)| {
                    format!("{}={}", k, property_to_db(x).unwrap_or_else(|| "null".to_string()))
                })
                .collect();
            Some(format!("{{{}}}", parts.join(", ")))
        }
    }
}

/// commons-beanutils `ConvertUtils.convert(String, int/Integer)`: a value that
/// cannot be converted becomes the converter's default, 0.
pub fn cast_int(s: &str) -> i32 {
    s.trim().parse::<i32>().unwrap_or(0)
}

/// commons-beanutils `ConvertUtils.convert(String, double/Double)`: default 0.0.
pub fn cast_double(s: &str) -> f64 {
    let t = s.trim();
    match t.parse::<f64>() {
        Ok(d) => d,
        Err(_) => match t {
            "NaN" => f64::NAN,
            "Infinity" | "+Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            _ => 0.0,
        },
    }
}

/// commons-beanutils `BooleanConverter`: unknown text becomes the default `false`.
pub fn cast_bool(s: &str) -> bool {
    matches!(
        s.trim().to_ascii_lowercase().as_str(),
        "true" | "yes" | "y" | "on" | "1"
    )
}

/// Java `String.split("\\s*,\\s*")` followed by Java's removal of trailing
/// empty strings, applied to every value of an `output:only` parameter.
pub fn split_commas(s: &str) -> Vec<String> {
    let mut parts: Vec<String> = s.split(',').map(|p| p.trim().to_string()).collect();
    while parts.last().map(|p| p.is_empty()).unwrap_or(false) {
        parts.pop();
    }
    parts
}

