mod tests {
    use super::*;

    #[test]
    fn java_double_formats_like_java() {
        assert_eq!(java_double(1.0), "1.0");
        assert_eq!(java_double(0.5), "0.5");
        assert_eq!(java_double(156543.03390625), "156543.03390625");
        assert_eq!(java_double(1e10), "1.0E10");
        assert_eq!(java_double(-2.002637639e7), "-2.002637639E7");
        assert_eq!(java_double(0.0001), "1.0E-4");
        assert_eq!(java_double(0.001), "0.001");
    }

