        assert_eq!(property_from_db("-3"), Value::from(-3));
        assert_eq!(property_from_db("3.0").as_f64(), Some(3.0));
        assert!(property_from_db("3.0").is_f64());
        assert_eq!(property_from_db("x"), Value::String("x".into()));
        assert_eq!(property_to_db(&Value::from(1)).as_deref(), Some("1"));
        assert_eq!(property_to_db(&serde_json::json!(1.5)).as_deref(), Some("1.5"));
        assert_eq!(property_to_db(&serde_json::json!(true)).as_deref(), Some("true"));
        assert_eq!(property_to_db(&Value::Null), None);
    }

