        assert_eq!(split_commas("a, b ,c"), vec!["a", "b", "c"]);
        assert_eq!(split_commas("a,,b,,"), vec!["a", "", "b"]);
        assert_eq!(split_commas(""), Vec::<String>::new());
    }
}

