//! Small helpers that reproduce the Java / Jackson / commons-lang / commons-beanutils
//! behaviour the original SHOGun-Core relies on (number formatting, string
//! to value conversion of the `Map<String, Object>` appearance properties,
//! and the coercion of filter request parameters).

use serde_json::Value;

/// `java.lang.Double.toString(double)`.
pub fn java_double(d: f64) -> String {
    if d.is_nan() {
        return "NaN".to_string();
    }
    if d.is_infinite() {
        return if d > 0.0 { "Infinity" } else { "-Infinity" }.to_string();
    }
    if d == 0.0 {
        return if d.is_sign_negative() { "-0.0" } else { "0.0" }.to_string();
    }
    let abs = d.abs();
    if (1e-3..1e7).contains(&abs) {
        let s = format!("{}", d);
        if s.contains('.') {
            s
        } else {
            format!("{}.0", s)
        }
    } else {
        let s = format!("{:e}", d);
        let (mantissa, exponent) = s.split_once('e').unwrap_or((&s, "0"));
        let mantissa = if mantissa.contains('.') {
            mantissa.to_string()
        } else {
            format!("{}.0", mantissa)
        };
        format!("{}E{}", mantissa, exponent)
    }
}

/// `org.apache.commons.lang3.math.NumberUtils.isParsable`.
pub fn is_parsable(s: &str) -> bool {
    if s.is_empty() {
        return false;
    }
    if s.ends_with('.') {
        return false;
    }
    let (body, start) = if let Some(rest) = s.strip_prefix('-') {
        if rest.is_empty() {
            return false;
        }
        (rest, 0)
    } else {
        (s, 0)
    };
    let _ = start;
    let mut points = 0;
    for ch in body.chars() {
        if ch == '.' {
            points += 1;
            if points > 1 {
                return false;
            }
        } else if !ch.is_ascii_digit() {
            return false;
        }
    }
    true
}

/// `NumberUtils.isDigits`.
fn is_digits(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| c.is_ascii_digit())
}

/// Converts a string stored in `LAYERAPPEARANCES_PROPERTIES.VALUE` back to the
/// best matching value, as `PropertyValueConverter.convertToEntityAttribute` does.
pub fn property_from_db(s: &str) -> Value {
    if s.eq_ignore_ascii_case("true") {
        return Value::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return Value::Bool(false);
    }
    if is_parsable(s) {
        if is_digits(s) || (s.starts_with('-') && is_digits(&s[1..])) {
            if let Ok(v) = s.parse::<i64>() {
                return Value::from(v);
            }
        }
        if let Ok(d) = s.parse::<f64>() {
            return serde_json::Number::from_f64(d)
                .map(Value::Number)
                .unwrap_or(Value::Null);
        }
    }
    Value::String(s.to_string())
}

