//! The SHOGun entities of the REST slice, with the state the Java objects hold.
//!
//! Every struct's `Default` is what the Java no-arg constructor produces: the
//! `created` timestamp is "now" (as `PersistentObject` sets it) and the
//! collections the constructor initialises are empty, the others are `null`.
//! The JSON produced by `to_json` is the Jackson serialisation of the object.

use chrono::NaiveDate;
use serde_json::{Map, Value};

pub const ROLE_ADMIN: &str = "ROLE_ADMIN";
pub const ROLE_USER: &str = "ROLE_USER";

/// Milliseconds since the epoch, the precision `joda` `DateTime` gives.
pub fn now_ms() -> i64 {
    chrono::Utc::now().timestamp_millis()
}

#[derive(Clone, Debug, PartialEq)]
pub struct Point {
    pub x: f64,
    pub y: f64,
}

impl Point {
    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("x".into(), num(self.x));
        m.insert("y".into(), num(self.y));
        Value::Object(m)
    }
}

pub fn num(d: f64) -> Value {
    serde_json::Number::from_f64(d).map(Value::Number).unwrap_or(Value::Null)
}

fn opt_num(d: Option<f64>) -> Value {
    d.map(num).unwrap_or(Value::Null)
}

fn opt_str(s: &Option<String>) -> Value {
    s.as_ref().map(|s| Value::String(s.clone())).unwrap_or(Value::Null)
}

fn opt_bool(b: Option<bool>) -> Value {
    b.map(Value::Bool).unwrap_or(Value::Null)
}

fn opt_int(i: Option<i32>) -> Value {
    i.map(|i| Value::from(i)).unwrap_or(Value::Null)
}

fn opt_id(i: Option<i32>) -> Value {
    opt_int(i)
}

fn list_f64(l: &Option<Vec<f64>>) -> Value {
    match l {
        Some(v) => Value::Array(v.iter().map(|d| num(*d)).collect()),
        None => Value::Null,
    }
}

fn list_str(l: &Option<Vec<String>>) -> Value {
    match l {
        Some(v) => Value::Array(v.iter().map(|s| Value::String(s.clone())).collect()),
        None => Value::Null,
    }
}

pub fn set_to_json<T>(l: &Option<Vec<T>>, f: impl Fn(&T) -> Value) -> Value {
    match l {
        Some(v) => Value::Array(v.iter().map(f).collect()),
        None => Value::Null,
    }
}

/// Keeps the first of equal elements, as `HashSet.add` does.
pub fn dedupe<T>(items: Vec<T>, eq: impl Fn(&T, &T) -> bool) -> Vec<T> {
    let mut out: Vec<T> = Vec::with_capacity(items.len());
    for it in items {
        if !out.iter().any(|o| eq(o, &it)) {
            out.push(it);
        }
    }
    out
}

fn set_eq<T>(a: &Option<Vec<T>>, b: &Option<Vec<T>>, eq: impl Fn(&T, &T) -> bool) -> bool {
    match (a, b) {
        (None, None) => true,
        (Some(x), Some(y)) => {
            x.len() == y.len() && x.iter().all(|e| y.iter().any(|f| eq(e, f)))
        }
        _ => false,
    }
}

// ---------------------------------------------------------------- Extent

#[derive(Clone, Debug)]
pub struct Extent {
    pub id: Option<i32>,
    pub created: i64,
    pub lower_left: Option<Point>,
    pub upper_right: Option<Point>,
    /// Set when the JSON replaced this extent: a SAVE_UPDATE cascade writes it.
    pub cascade: bool,
}

impl Default for Extent {
    fn default() -> Self {
        Extent { id: None, created: now_ms(), lower_left: None, upper_right: None, cascade: false }
    }
}

impl Extent {
    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_id(self.id));
        m.insert("lowerLeft".into(), self.lower_left.as_ref().map(|p| p.to_json()).unwrap_or(Value::Null));
        m.insert("upperRight".into(), self.upper_right.as_ref().map(|p| p.to_json()).unwrap_or(Value::Null));
        Value::Object(m)
    }
}

pub fn extent_eq(a: &Extent, b: &Extent) -> bool {
    a.created == b.created && a.lower_left == b.lower_left && a.upper_right == b.upper_right
}

// ---------------------------------------------------------------- TileGrid

#[derive(Clone, Debug)]
pub struct TileGrid {
    pub id: Option<i32>,
    pub created: i64,
    /// `WmtsTileGrid` (has `matrixIds`) rather than a plain `TileGrid`.
    pub wmts: bool,
    pub tile_type: Option<String>,
    pub origin: Option<Point>,
    pub extent: Option<Extent>,
    pub tile_size: Option<i32>,
    pub resolutions: Option<Vec<f64>>,
    pub matrix_ids: Option<Vec<String>>,
    pub cascade: bool,
    pub cascade_extent: bool,
}

impl Default for TileGrid {
    fn default() -> Self {
        TileGrid {
            id: None,
            created: now_ms(),
            wmts: false,
            tile_type: None,
            origin: None,
            extent: None,
            tile_size: Some(256),
            resolutions: None,
            matrix_ids: None,
            cascade: false,
            cascade_extent: false,
        }
    }
}

impl TileGrid {
    pub fn wmts_default() -> Self {
        TileGrid { wmts: true, ..TileGrid::default() }
    }

    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_id(self.id));
        m.insert("type".into(), opt_str(&self.tile_type));
        m.insert("tileGridOrigin".into(), self.origin.as_ref().map(|p| p.to_json()).unwrap_or(Value::Null));
        m.insert(
            "tileGridExtent".into(),
            self.extent.as_ref().map(|e| e.to_json()).unwrap_or(Value::Null),
        );
        m.insert("tileSize".into(), opt_int(self.tile_size));
        m.insert("tileGridResolutions".into(), list_f64(&self.resolutions));
        if self.wmts {
            m.insert("matrixIds".into(), list_str(&self.matrix_ids));
        }
        Value::Object(m)
    }
}

pub fn tilegrid_eq(a: &TileGrid, b: &TileGrid) -> bool {
    a.created == b.created && a.tile_type == b.tile_type && a.origin == b.origin
}

// ---------------------------------------------------------------- Appearance

#[derive(Clone, Debug)]
pub struct Appearance {
    pub id: Option<i32>,
    pub created: i64,
    pub attribution: Option<String>,
    pub hoverable: Option<bool>,
    pub clickable: Option<bool>,
    pub hover_template: Option<String>,
    /// `null` or the map's entries as the JSON gave them (typed values).
    pub properties: Option<Vec<(String, Value)>>,
    pub name: Option<String>,
    pub max_resolution: Option<f64>,
    pub min_resolution: Option<f64>,
    pub opacity: Option<f64>,
    pub visible: Option<bool>,
    pub cascade: bool,
}

impl Default for Appearance {
    fn default() -> Self {
        Appearance {
            id: None,
            created: now_ms(),
            attribution: None,
            hoverable: None,
            clickable: None,
            hover_template: None,
            properties: Some(Vec::new()),
            name: None,
            max_resolution: None,
            min_resolution: None,
            opacity: None,
            visible: None,
            cascade: false,
        }
    }
}

impl Appearance {
    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_id(self.id));
        m.insert("attribution".into(), opt_str(&self.attribution));
        m.insert("hoverable".into(), opt_bool(self.hoverable));
        m.insert("clickable".into(), opt_bool(self.clickable));
        m.insert("hoverTemplate".into(), opt_str(&self.hover_template));
        let props = match &self.properties {
            Some(entries) => {
                let mut pm = Map::new();
                for (k, v) in entries {
                    pm.insert(k.clone(), v.clone());
                }
                Value::Object(pm)
            }
            None => Value::Null,
        };
        m.insert("properties".into(), props);
        m.insert("name".into(), opt_str(&self.name));
        m.insert("maxResolution".into(), opt_num(self.max_resolution));
        m.insert("minResolution".into(), opt_num(self.min_resolution));
        m.insert("opacity".into(), opt_num(self.opacity));
        m.insert("visible".into(), opt_bool(self.visible));
        Value::Object(m)
    }
}

// ---------------------------------------------------------------- Role

#[derive(Clone, Debug)]
pub struct Role {
    pub id: Option<i32>,
    pub created: i64,
    pub name: Option<String>,
    pub description: Option<String>,
}

impl Default for Role {
    fn default() -> Self {
        Role { id: None, created: now_ms(), name: None, description: None }
    }
}

impl Role {
    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_id(self.id));
        m.insert("name".into(), opt_str(&self.name));
        m.insert("description".into(), opt_str(&self.description));
        Value::Object(m)
    }
}

pub fn role_eq(a: &Role, b: &Role) -> bool {
    a.created == b.created && a.name == b.name && a.description == b.description
}

// ---------------------------------------------------------------- User

#[derive(Clone, Debug)]
pub struct User {
    pub id: Option<i32>,
    pub created: i64,
    pub first_name: Option<String>,
    pub last_name: Option<String>,
    pub email: Option<String>,
    pub birthday: Option<NaiveDate>,
    pub language: Option<String>,
    pub account_name: Option<String>,
    pub password: Option<String>,
    pub active: bool,
    pub roles: Option<Vec<Role>>,
    /// Ids of the groups; the JSON writes the groups as ids only.
    pub user_groups: Option<Vec<i32>>,
}

impl Default for User {
    fn default() -> Self {
        User {
            id: None,
            created: now_ms(),
            first_name: None,
            last_name: None,
            email: None,
            birthday: None,
            language: None,
            account_name: None,
            password: None,
            active: false,
            roles: Some(Vec::new()),
            user_groups: Some(Vec::new()),
        }
    }
}

impl User {
    pub fn to_json(&self, internal: bool) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_id(self.id));
        m.insert("firstName".into(), opt_str(&self.first_name));
        m.insert("lastName".into(), opt_str(&self.last_name));
        m.insert("email".into(), opt_str(&self.email));
        m.insert(
            "birthday".into(),
            self.birthday.map(|d| Value::String(d.format("%Y-%m-%d").to_string())).unwrap_or(Value::Null),
        );
        m.insert("language".into(), opt_str(&self.language));
        m.insert("accountName".into(), opt_str(&self.account_name));
        if internal {
            m.insert("password".into(), opt_str(&self.password));
        }
        m.insert("active".into(), Value::Bool(self.active));
        m.insert("roles".into(), set_to_json(&self.roles, |r| r.to_json()));
        m.insert(
            "userGroups".into(),
            match &self.user_groups {
                Some(ids) => Value::Array(ids.iter().map(|i| Value::from(*i)).collect()),
                None => Value::Null,
            },
        );
        Value::Object(m)
    }
}

pub fn user_eq(a: &User, b: &User) -> bool {
    a.created == b.created
        && a.first_name == b.first_name
        && a.last_name == b.last_name
        && a.email == b.email
        && a.birthday == b.birthday
        && a.language == b.language
        && a.account_name == b.account_name
        && a.password == b.password
        && a.active == b.active
}

