#[derive(Clone, Debug)]
pub struct UserGroup {
    pub id: Option<i32>,
    pub created: i64,
    pub name: Option<String>,
    pub owner: Option<User>,
    pub members: Option<Vec<User>>,
    pub roles: Option<Vec<Role>>,
}

impl Default for UserGroup {
    fn default() -> Self {
        UserGroup {
            id: None,
            created: now_ms(),
            name: None,
            owner: None,
            members: Some(Vec::new()),
            roles: Some(Vec::new()),
        }
    }
}

impl UserGroup {
    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_id(self.id));
        m.insert("name".into(), opt_str(&self.name));
        m.insert(
            "owner".into(),
            self.owner.as_ref().map(|u| u.to_json(false)).unwrap_or(Value::Null),
        );
        m.insert("members".into(), set_to_json(&self.members, |u| u.to_json(false)));
        m.insert("roles".into(), set_to_json(&self.roles, |r| r.to_json()));
        Value::Object(m)
    }
}

pub fn group_eq(a: &UserGroup, b: &UserGroup) -> bool {
    a.created == b.created
        && a.name == b.name
        && match (&a.owner, &b.owner) {
            (None, None) => true,
            (Some(x), Some(y)) => user_eq(x, y),
            _ => false,
        }
        && set_eq(&a.members, &b.members, user_eq)
        && set_eq(&a.roles, &b.roles, role_eq)
}

