#[derive(Clone, Debug)]
pub struct DataSource {
    pub id: Option<i32>,
    pub created: i64,
    pub name: Option<String>,
    pub ds_type: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    pub kind: DsKind,
}

impl ImageFields {
    pub fn empty() -> Self {
        ImageFields {
            width: 0,
            height: 0,
            version: None,
            layer_names: None,
            layer_styles: None,
            requestable_by_path: None,
            custom_request_path: None,
        }
    }

    fn write_json(&self, m: &mut Map<String, Value>) {
        m.insert("width".into(), Value::from(self.width));
        m.insert("height".into(), Value::from(self.height));
        m.insert("version".into(), opt_str(&self.version));
        m.insert("layerNames".into(), opt_str(&self.layer_names));
        m.insert("layerStyles".into(), opt_str(&self.layer_styles));
        m.insert("requestableByPath".into(), opt_bool(self.requestable_by_path));
        m.insert("customRequestPath".into(), opt_str(&self.custom_request_path));
    }
}

impl DataSource {
    pub fn kind_name(&self) -> &'static str {
        match self.kind {
            DsKind::ImageWms(_) => "ImageWms",
            DsKind::TileWms { .. } => "TileWms",
            DsKind::Wfs { .. } => "Wfs",
            DsKind::Wmts { .. } => "Wmts",
            DsKind::Xyz { .. } => "Xyz",
        }
    }

    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_id(self.id));
        m.insert("name".into(), opt_str(&self.name));
        m.insert("type".into(), opt_str(&self.ds_type));
        m.insert("url".into(), opt_str(&self.url));
        m.insert("format".into(), opt_str(&self.format));
        match &self.kind {
            DsKind::ImageWms(f) => f.write_json(&mut m),
            DsKind::TileWms { img, tile_grid, request_with_tiled } => {
                img.write_json(&mut m);
                m.insert(
                    "tileGrid".into(),
                    tile_grid.as_ref().map(|t| t.to_json()).unwrap_or(Value::Null),
                );
                m.insert("requestWithTiled".into(), opt_bool(*request_with_tiled));
            }
            DsKind::Wfs { version, type_name, type_names } => {
                m.insert("version".into(), opt_str(version));
                m.insert("typeName".into(), opt_str(type_name));
                m.insert("typeNames".into(), opt_str(type_names));
            }
            DsKind::Wmts {
                tile_grid,
                urls,
                wmts_layer,
                wmts_style,
                projection,
                matrix_set,
                request_encoding,
                capabilities_url,
            } => {
                m.insert(
                    "tileGrid".into(),
                    tile_grid.as_ref().map(|t| t.to_json()).unwrap_or(Value::Null),
                );
                m.insert("urls".into(), list_str(urls));
                m.insert("wmtsLayer".into(), opt_str(wmts_layer));
                m.insert("wmtsStyle".into(), opt_str(wmts_style));
                m.insert("projection".into(), opt_str(projection));
                m.insert("matrixSet".into(), opt_str(matrix_set));
                m.insert("requestEncoding".into(), opt_str(request_encoding));
                m.insert("capabilitiesUrl".into(), opt_str(capabilities_url));
            }
            DsKind::Xyz { center, extent, resolutions, tile_size } => {
                m.insert("center".into(), center.as_ref().map(|p| p.to_json()).unwrap_or(Value::Null));
                m.insert("extent".into(), extent.as_ref().map(|e| e.to_json()).unwrap_or(Value::Null));
                m.insert("resolutions".into(), list_f64(resolutions));
                m.insert("tileSize".into(), opt_int(*tile_size));
            }
        }
        Value::Object(m)
    }
}

// ---------------------------------------------------------------- Lists of entities

/// The six resources of the slice.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Res {
    Users,
    Groups,
    Roles,
    Layers,
    DataSources,
    Appearances,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FieldKind {
    Str,
    Int,
    Bool,
    Dbl,
}

impl Res {
    pub fn parse(s: &str) -> Option<Res> {
        Some(match s {
            "users" => Res::Users,
            "groups" => Res::Groups,
            "roles" => Res::Roles,
            "layers" => Res::Layers,
            "layerdatasources" => Res::DataSources,
            "layerappearances" => Res::Appearances,
            _ => return None,
        })
    }

    /// The Java class the controller serves (its simple name, for logs).
    pub fn class_name(self) -> &'static str {
        match self {
            Res::Users => "User",
            Res::Groups => "UserGroup",
            Res::Roles => "Role",
            Res::Layers => "Layer",
            Res::DataSources => "LayerDataSource",
            Res::Appearances => "LayerAppearance",
        }
    }

    /// Private, non-static primitive/wrapper/String fields of the class
    /// hierarchy: the names `output:only` and the equality filters accept.
    pub fn scalar_fields(self) -> &'static [(&'static str, FieldKind)] {
        use FieldKind::*;
        match self {
            Res::Users => &[
                ("id", Int),
                ("firstName", Str),
                ("lastName", Str),
                ("email", Str),
                ("accountName", Str),
                ("password", Str),
                ("active", Bool),
            ],
            Res::Groups => &[("id", Int), ("name", Str)],
            Res::Roles => &[("id", Int), ("name", Str), ("description", Str)],
            Res::Layers => &[("id", Int), ("name", Str), ("description", Str)],
            Res::DataSources => &[
                ("id", Int),
                ("name", Str),
                ("type", Str),
                ("url", Str),
                ("format", Str),
            ],
            Res::Appearances => &[
                ("id", Int),
                ("attribution", Str),
                ("hoverable", Bool),
                ("clickable", Bool),
                ("hoverTemplate", Str),
                ("name", Str),
                ("maxResolution", Dbl),
                ("minResolution", Dbl),
                ("opacity", Dbl),
                ("visible", Bool),
            ],
        }
    }
}

/// One loaded entity of any of the six resources.
#[derive(Clone, Debug)]
pub enum Ent {
    User(User),
    Group(UserGroup),
    Role(Role),
    Layer(Layer),
    Ds(DataSource),
    App(Appearance),
}

impl Ent {
    pub fn res(&self) -> Res {
        match self {
            Ent::User(_) => Res::Users,
            Ent::Group(_) => Res::Groups,
            Ent::Role(_) => Res::Roles,
            Ent::Layer(_) => Res::Layers,
            Ent::Ds(_) => Res::DataSources,
            Ent::App(_) => Res::Appearances,
        }
    }

    pub fn id(&self) -> Option<i32> {
        match self {
            Ent::User(e) => e.id,
            Ent::Group(e) => e.id,
            Ent::Role(e) => e.id,
            Ent::Layer(e) => e.id,
            Ent::Ds(e) => e.id,
            Ent::App(e) => e.id,
        }
    }

    /// Jackson output of the object. `internal` also includes the write-only
    /// password, which the filter uses but the REST output never shows.
    pub fn to_json(&self, internal: bool) -> Value {
        match self {
            Ent::User(e) => e.to_json(internal),
            Ent::Group(e) => e.to_json(),
            Ent::Role(e) => e.to_json(),
            Ent::Layer(e) => e.to_json(),
            Ent::Ds(e) => e.to_json(),
            Ent::App(e) => e.to_json(),
        }
    }

    /// The object a default-constructed instance serialises to.
    pub fn default_json(res: Res) -> Value {
        match res {
            Res::Users => User::default().to_json(false),
            Res::Groups => UserGroup::default().to_json(),
            Res::Roles => Role::default().to_json(),
            Res::Layers => Layer::default().to_json(),
            Res::DataSources => Value::Null,
            Res::Appearances => Appearance::default().to_json(),
        }
    }
}

/// The projection `output:only` builds: a default-constructed object with the
/// listed scalar fields set from the database row.
pub fn project(res: Res, full: &Value, fields: &[String]) -> Value {
    let mut base = match Ent::default_json(res) {
        Value::Object(m) => m,
        _ => Map::new(),
    };
    if let Value::Object(src) = full {
        for f in fields {
            if let Some(slot) = base.get_mut(f) {
                if let Some(v) = src.get(f) {
                    *slot = v.clone();
                }
            }
        }
    }
    Value::Object(base)
}

