// ---------------------------------------------------------------- DataSource

#[derive(Clone, Debug)]
pub struct ImageFields {
    pub width: i32,
    pub height: i32,
    pub version: Option<String>,
    pub layer_names: Option<String>,
    pub layer_styles: Option<String>,
    pub requestable_by_path: Option<bool>,
    pub custom_request_path: Option<String>,
}

#[derive(Clone, Debug)]
pub enum DsKind {
    ImageWms(ImageFields),
    TileWms {
        img: ImageFields,
        tile_grid: Option<TileGrid>,
        request_with_tiled: Option<bool>,
    },
    Wfs {
        version: Option<String>,
        type_name: Option<String>,
        type_names: Option<String>,
    },
    Wmts {
        tile_grid: Option<TileGrid>,
        urls: Option<Vec<String>>,
        wmts_layer: Option<String>,
        wmts_style: Option<String>,
        projection: Option<String>,
        matrix_set: Option<String>,
        request_encoding: Option<String>,
        capabilities_url: Option<String>,
    },
    Xyz {
        center: Option<Point>,
        extent: Option<Extent>,
        resolutions: Option<Vec<f64>>,
        tile_size: Option<i32>,
    },
}

#[derive(Clone, Debug)]
pub struct DataSource {
    pub id: Option<i32>,
    pub created: i64,
    pub name: Option<String>,
    pub ds_type: Option<String>,
    pub url: Option<String>,
    pub format: Option<String>,
    pub kind: DsKind,
}

impl ImageFields {
    pub fn empty() -> Self {
        ImageFields {
            width: 0,
            height: 0,
            version: None,
            layer_names: None,
            layer_styles: None,
            requestable_by_path: None,
            custom_request_path: None,
        }
    }

    fn write_json(&self, m: &mut Map<String, Value>) {
        m.insert("width".into(), Value::from(self.width));
        m.insert("height".into(), Value::from(self.height));
        m.insert("version".into(), opt_str(&self.version));
        m.insert("layerNames".into(), opt_str(&self.layer_names));
        m.insert("layerStyles".into(), opt_str(&self.layer_styles));
        m.insert("requestableByPath".into(), opt_bool(self.requestable_by_path));
        m.insert("customRequestPath".into(), opt_str(&self.custom_request_path));
    }
}

impl DataSource {
    pub fn kind_name(&self) -> &'static str {
        match self.kind {
            DsKind::ImageWms(_) => "ImageWms",
            DsKind::TileWms { .. } => "TileWms",
            DsKind::Wfs { .. } => "Wfs",
            DsKind::Wmts { .. } => "Wmts",
            DsKind::Xyz { .. } => "Xyz",
        }
    }

    pub fn to_json(&self) -> Value {
        let mut m = Map::new();
        m.insert("id".into(), opt_id(self.id));
        m.insert("name".into(), opt_str(&self.name));
        m.insert("type".into(), opt_str(&self.ds_type));
        m.insert("url".into(), opt_str(&self.url));
        m.insert("format".into(), opt_str(&self.format));
        match &self.kind {
            DsKind::ImageWms(f) => f.write_json(&mut m),
            DsKind::TileWms { img, tile_grid, request_with_tiled } => {
                img.write_json(&mut m);
                m.insert(
                    "tileGrid".into(),
                    tile_grid.as_ref().map(|t| t.to_json()).unwrap_or(Value::Null),
                );
                m.insert("requestWithTiled".into(), opt_bool(*request_with_tiled));
            }
            DsKind::Wfs { version, type_name, type_names } => {
                m.insert("version".into(), opt_str(version));
                m.insert("typeName".into(), opt_str(type_name));
                m.insert("typeNames".into(), opt_str(type_names));
            }
            DsKind::Wmts {
                tile_grid,
                urls,
                wmts_layer,
                wmts_style,
                projection,
                matrix_set,
                request_encoding,
                capabilities_url,
            } => {
                m.insert(
                    "tileGrid".into(),
                    tile_grid.as_ref().map(|t| t.to_json()).unwrap_or(Value::Null),
                );
                m.insert("urls".into(), list_str(urls));
                m.insert("wmtsLayer".into(), opt_str(wmts_layer));
                m.insert("wmtsStyle".into(), opt_str(wmts_style));
                m.insert("projection".into(), opt_str(projection));
                m.insert("matrixSet".into(), opt_str(matrix_set));
                m.insert("requestEncoding".into(), opt_str(request_encoding));
                m.insert("capabilitiesUrl".into(), opt_str(capabilities_url));
            }
            DsKind::Xyz { center, extent, resolutions, tile_size } => {
                m.insert("center".into(), center.as_ref().map(|p| p.to_json()).unwrap_or(Value::Null));
                m.insert("extent".into(), extent.as_ref().map(|e| e.to_json()).unwrap_or(Value::Null));
                m.insert("resolutions".into(), list_f64(resolutions));
                m.insert("tileSize".into(), opt_int(*tile_size));
            }
        }
        Value::Object(m)
    }
}

// ---------------------------------------------------------------- Lists of entities

/// The six resources of the slice.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Res {
    Users,
    Groups,
    Roles,
    Layers,
    DataSources,
    Appearances,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FieldKind {
    Str,
    Int,
    Bool,
    Dbl,
}

impl Res {
    pub fn parse(s: &str) -> Option<Res> {
        Some(match s {
            "users" => Res::Users,
            "groups" => Res::Groups,
            "roles" => Res::Roles,
            "layers" => Res::Layers,
            "layerdatasources" => Res::DataSources,
            "layerappearances" => Res::Appearances,
            _ => return None,
        })
    }

    /// The Java class the controller serves (its simple name, for logs).
    pub fn class_name(self) -> &'static str {
        match self {
            Res::Users => "User",
            Res::Groups => "UserGroup",
            Res::Roles => "Role",
            Res::Layers => "Layer",
            Res::DataSources => "LayerDataSource",
            Res::Appearances => "LayerAppearance",
        }
    }

    /// Private, non-static primitive/wrapper/String fields of the class
    /// hierarchy: the names `output:only` and the equality filters accept.
    pub fn scalar_fields(self) -> &'static [(&'static str, FieldKind)] {
        use FieldKind::*;
        match self {
            Res::Users => &[
                ("id", Int),
                ("firstName", Str),
                ("lastName", Str),
                ("email", Str),
                ("accountName", Str),
                ("password", Str),
                ("active", Bool),
            ],
            Res::Groups => &[("id", Int), ("name", Str)],
            Res::Roles => &[("id", Int), ("name", Str), ("description", Str)],
            Res::Layers => &[("id", Int), ("name", Str), ("description", Str)],
            Res::DataSources => &[
                ("id", Int),
                ("name", Str),
                ("type", Str),
                ("url", Str),
                ("format", Str),
            ],
            Res::Appearances => &[
                ("id", Int),
                ("attribution", Str),
                ("hoverable", Bool),
                ("clickable", Bool),
                ("hoverTemplate", Str),
                ("name", Str),
                ("maxResolution", Dbl),
                ("minResolution", Dbl),
                ("opacity", Dbl),
                ("visible", Bool),
            ],
        }
    }
}

/// One loaded entity of any of the six resources.
#[derive(Clone, Debug)]
pub enum Ent {
    User(User),
    Group(UserGroup),
    Role(Role),
    Layer(Layer),
    Ds(DataSource),
    App(Appearance),
}

impl Ent {
    pub fn res(&self) -> Res {
        match self {
            Ent::User(_) => Res::Users,
            Ent::Group(_) => Res::Groups,
            Ent::Role(_) => Res::Roles,
            Ent::Layer(_) => Res::Layers,
            Ent::Ds(_) => Res::DataSources,
            Ent::App(_) => Res::Appearances,
        }
    }

    pub fn id(&self) -> Option<i32> {
        match self {
            Ent::User(e) => e.id,
            Ent::Group(e) => e.id,
            Ent::Role(e) => e.id,
            Ent::Layer(e) => e.id,
            Ent::Ds(e) => e.id,
            Ent::App(e) => e.id,
        }
    }

    /// Jackson output of the object. `internal` also includes the write-only
    /// password, which the filter uses but the REST output never shows.
    pub fn to_json(&self, internal: bool) -> Value {
        match self {
            Ent::User(e) => e.to_json(internal),
            Ent::Group(e) => e.to_json(),
            Ent::Role(e) => e.to_json(),
            Ent::Layer(e) => e.to_json(),
            Ent::Ds(e) => e.to_json(),
            Ent::App(e) => e.to_json(),
        }
    }

    /// The object a default-constructed instance serialises to.
    pub fn default_json(res: Res) -> Value {
        match res {
            Res::Users => User::default().to_json(false),
            Res::Groups => UserGroup::default().to_json(),
            Res::Roles => Role::default().to_json(),
            Res::Layers => Layer::default().to_json(),
            Res::DataSources => Value::Null,
            Res::Appearances => Appearance::default().to_json(),
        }
    }
}

/// The projection `output:only` builds: a default-constructed object with the
/// listed scalar fields set from the database row.
pub fn project(res: Res, full: &Value, fields: &[String]) -> Value {
    let mut base = match Ent::default_json(res) {
        Value::Object(m) => m,
        _ => Map::new(),
    };
    if let Value::Object(src) = full {
        for f in fields {
            if let Some(slot) = base.get_mut(f) {
                if let Some(v) = src.get(f) {
                    *slot = v.clone();
                }
            }
        }
    }
    Value::Object(base)
}

input.content:
//! Jackson-like reading of a JSON object into the entity model.
//!
//! `apply` is what `ObjectMapper.readerForUpdating(entity).readValue(json)`
//! does: keys present in the JSON are set, others keep their value, unknown
//! keys fail, and `@JsonIgnore`d keys are skipped. Nested objects are always
//! new instances, as Jackson creates them, and sets drop equal duplicates the
//! way `HashSet` does.

use chrono::NaiveDate;
use serde_json::{Map, Value};

use crate::model::*;

/// Any Jackson failure. The handlers decide which status it becomes.
#[derive(Debug)]
pub struct Bad;

pub type PR<T> = Result<T, Bad>;
type M = Map<String, Value>;

pub fn object(v: &Value) -> PR<&M> {
    v.as_object().ok_or(Bad)
}

pub fn opt_string(v: &Value) -> PR<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(s.clone())),
        Value::Number(n) => Ok(Some(n.to_string())),
        Value::Bool(b) => Ok(Some(b.to_string())),
        _ => Err(Bad),
    }
}

pub fn opt_i32(v: &Value) -> PR<Option<i32>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => {
            let i = if let Some(i) = n.as_i64() {
                i
            } else {
                let f = n.as_f64().ok_or(Bad)?;
                if !f.is_finite() || f.abs() > i32::MAX as f64 + 1.0 {
                    return Err(Bad);
                }
                f.trunc() as i64
            };
            i32::try_from(i).map(Some).map_err(|_| Bad)
        }
        Value::String(s) => s.trim().parse::<i32>().map(Some).map_err(|_| Bad),
        _ => Err(Bad),
    }
}

pub fn prim_i32(v: &Value) -> PR<i32> {
    Ok(opt_i32(v)?.unwrap_or(0))
}

pub fn opt_f64(v: &Value) -> PR<Option<f64>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => Ok(Some(n.as_f64().ok_or(Bad)?)),
        Value::String(s) => s.trim().parse::<f64>().map(Some).map_err(|_| Bad),
        _ => Err(Bad),
    }
}

pub fn opt_bool(v: &Value) -> PR<Option<bool>> {
    match v {
        Value::Null => Ok(None),
        Value::Bool(b) => Ok(Some(*b)),
        Value::Number(n) => Ok(Some(n.as_f64().unwrap_or(0.0) != 0.0)),
        Value::String(s) => match s.to_ascii_lowercase().as_str() {
            "true" => Ok(Some(true)),
            "false" => Ok(Some(false)),
            _ => Err(Bad),
        },
        _ => Err(Bad),
    }
}

pub fn prim_bool(v: &Value) -> PR<bool> {
    Ok(opt_bool(v)?.unwrap_or(false))
}

fn opt_date(v: &Value) -> PR<Option<NaiveDate>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => NaiveDate::parse_from_str(s.trim(), "%Y-%m-%d").map(Some).map_err(|_| Bad),
        _ => Err(Bad),
    }
}

fn opt_point(v: &Value) -> PR<Option<Point>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => Ok(Some(Point {
            x: prim_f64(m.get("x").unwrap_or(&Value::Null))?,
            y: prim_f64(m.get("y").unwrap_or(&Value::Null))?,
        })),
        _ => Err(Bad),
    }
}

fn prim_f64(v: &Value) -> PR<f64> {
    Ok(opt_f64(v)?.unwrap_or(0.0))
}

fn opt_list<T>(v: &Value, mut f: impl FnMut(&Value) -> PR<T>) -> PR<Option<Vec<T>>> {
    match v {
        Value::Null => Ok(None),
        Value::Array(items) => {
            let mut out = Vec::with_capacity(items.len());
            for it in items {
                out.push(f(it)?);
            }
            Ok(Some(out))
        }
        _ => Err(Bad),
    }
}

fn opt_str_list(v: &Value) -> PR<Option<Vec<String>>> {
    opt_list(v, |x| match x {
        Value::String(s) => Ok(s.clone()),
        Value::Number(n) => Ok(n.to_string()),
        _ => Err(Bad),
    })
}

fn opt_f64_list(v: &Value) -> PR<Option<Vec<f64>>> {
    opt_list(v, |x| opt_f64(x)?.ok_or(Bad))
}

fn ignored(k: &str) -> bool {
    matches!(k, "created" | "modified" | "userPermissions" | "groupPermissions")
}

// ---------------------------------------------------------------- Extent

impl Extent {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "lowerLeft" => self.lower_left = opt_point(v)?,
                "upperRight" => self.upper_right = opt_point(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn extent_from(v: &Value) -> PR<Option<Extent>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => {
            let mut e = Extent::default();
            e.apply(m)?;
            e.cascade = true;
            Ok(Some(e))
        }
        _ => Err(Bad),
    }
}

// ---------------------------------------------------------------- TileGrid

impl TileGrid {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "type" => self.tile_type = opt_string(v)?,
                "tileGridOrigin" => self.origin = opt_point(v)?,
                "tileGridExtent" => self.extent = extent_from(v)?,
                "tileSize" => self.tile_size = opt_i32(v)?,
                "tileGridResolutions" => self.resolutions = opt_f64_list(v)?,
                "matrixIds" if self.wmts => self.matrix_ids = opt_str_list(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn tilegrid_from(v: &Value, wmts: bool) -> PR<Option<TileGrid>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => {
            let mut t = if wmts { TileGrid::wmts_default() } else { TileGrid::default() };
            t.apply(m)?;
            t.cascade = true;
            Ok(Some(t))
        }
        _ => Err(Bad),
    }
}

// ---------------------------------------------------------------- Appearance

impl Appearance {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "attribution" => self.attribution = opt_string(v)?,
                "hoverable" => self.hoverable = opt_bool(v)?,
                "clickable" => self.clickable = opt_bool(v)?,
                "hoverTemplate" => self.hover_template = opt_string(v)?,
                "properties" => {
                    self.properties = match v {
                        Value::Null => None,
                        Value::Object(pm) => {
                            Some(pm.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
                        }
                        _ => return Err(Bad),
                    }
                }
                "name" => self.name = opt_string(v)?,
                "maxResolution" => self.max_resolution = opt_f64(v)?,
                "minResolution" => self.min_resolution = opt_f64(v)?,
                "opacity" => self.opacity = opt_f64(v)?,
                "visible" => self.visible = opt_bool(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn appearance_from(v: &Value) -> PR<Option<Appearance>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => {
            let mut a = Appearance::default();
            a.apply(m)?;
            a.cascade = true;
            Ok(Some(a))
        }
        _ => Err(Bad),
    }
}

// ---------------------------------------------------------------- Role

impl Role {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "name" => self.name = opt_string(v)?,
                "description" => self.description = opt_string(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn role_from(v: &Value) -> PR<Role> {
    let mut r = Role::default();
    r.apply(object(v)?)?;
    Ok(r)
}

// ---------------------------------------------------------------- User

fn group_ref(v: &Value) -> PR<i32> {
    match v {
        Value::Number(_) | Value::String(_) => opt_i32(v)?.ok_or(Bad),
        Value::Object(m) => opt_i32(m.get("id").unwrap_or(&Value::Null))?.ok_or(Bad),
        _ => Err(Bad),
    }
}

impl User {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "firstName" => self.first_name = opt_string(v)?,
                "lastName" => self.last_name = opt_string(v)?,
                "email" => self.email = opt_string(v)?,
                "birthday" => self.birthday = opt_date(v)?,
                "language" => self.language = opt_string(v)?,
                "accountName" => self.account_name = opt_string(v)?,
                "password" => self.password = opt_string(v)?,
                "active" => self.active = prim_bool(v)?,
                "roles" => {
                    self.roles = opt_list(v, role_from)?.map(|r| dedupe(r, role_eq));
                }
                "userGroups" => {
                    self.user_groups = opt_list(v, group_ref)?.map(|ids| {
                        dedupe(ids, |a, b| a == b)
                    });
                }
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn user_from(v: &Value) -> PR<User> {
    let mut u = User::default();
    u.apply(object(v)?)?;
    Ok(u)
}

fn opt_user_from(v: &Value) -> PR<Option<User>> {
    match v {
        Value::Null => Ok(None),
        _ => user_from(v).map(Some),
    }
}

// ---------------------------------------------------------------- UserGroup

impl UserGroup {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "name" => self.name = opt_string(v)?,
                "owner" => self.owner = opt_user_from(v)?,
                "members" => {
                    self.members = opt_list(v, user_from)?.map(|u| dedupe(u, user_eq));
                }
                "roles" => {
                    self.roles = opt_list(v, role_from)?.map(|r| dedupe(r, role_eq));
                }
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------- Layer

impl Layer {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "name" => self.name = opt_string(v)?,
                "description" => self.description = opt_string(v)?,
                // LayerDataSource is abstract: Jackson cannot build one.
                "source" => match v {
                    Value::Null => self.source = None,
                    _ => return Err(Bad),
                },
                "appearance" => self.appearance = appearance_from(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------- DataSource

impl ImageFields {
    /// Returns `Ok(false)` if `k` is not a property of an image WMS.
    fn apply_key(&mut self, k: &str, v: &Value) -> PR<bool> {
        match k {
            "width" => self.width = prim_i32(v)?,
            "height" => self.height = prim_i32(v)?,
            "version" => self.version = opt_string(v)?,
            "layerNames" => self.layer_names = opt_string(v)?,
            "layerStyles" => self.layer_styles = opt_string(v)?,
            "requestableByPath" => self.requestable_by_path = opt_bool(v)?,
            "customRequestPath" => self.custom_request_path = opt_string(v)?,
            _ => return Ok(false),
        }
        Ok(true)
    }
}

impl DataSource {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "name" => self.name = opt_string(v)?,
                "type" => self.ds_type = opt_string(v)?,
                "url" => self.url = opt_string(v)?,
                "format" => self.format = opt_string(v)?,
                k if ignored(k) => {}
                k => {
                    if !self.apply_kind_key(k, v)? {
                        return Err(Bad);
                    }
                }
            }
        }
        Ok(())
    }

    /// Returns `Ok(false)` if the key is not a property of this subclass.
    fn apply_kind_key(&mut self, k: &str, v: &Value) -> PR<bool> {
        match &mut self.kind {
            DsKind::ImageWms(f) => f.apply_key(k, v),
            DsKind::TileWms { img, tile_grid, request_with_tiled } => {
                if img.apply_key(k, v)? {
                    return Ok(true);
                }
                match k {
                    "tileGrid" => *tile_grid = tilegrid_from(v, false)?,
                    "requestWithTiled" => *request_with_tiled = opt_bool(v)?,
                    _ => return Ok(false),
                }
                Ok(true)
            }
            DsKind::Wfs { version, type_name, type_names } => {
                match k {
                    "version" => *version = opt_string(v)?,
                    "typeName" => *type_name = opt_string(v)?,
                    "typeNames" => *type_names = opt_string(v)?,
                    _ => return Ok(false),
                }
                Ok(true)
            }
            DsKind::Wmts {
                tile_grid,
                urls,
                wmts_layer,
                wmts_style,
                projection,
                matrix_set,
                request_encoding,
                capabilities_url,
            } => {
                match k {
                    "tileGrid" => *tile_grid = tilegrid_from(v, true)?,
                    "urls" => *urls = opt_str_list(v)?,
                    "wmtsLayer" => *wmts_layer = opt_string(v)?,
                    "wmtsStyle" => *wmts_style = opt_string(v)?,
                    "projection" => *projection = opt_string(v)?,
                    "matrixSet" => *matrix_set = opt_string(v)?,
                    "requestEncoding" => *request_encoding = opt_string(v)?,
                    "capabilitiesUrl" => *capabilities_url = opt_string(v)?,
                    _ => return Ok(false),
                }
                Ok(true)
            }
            DsKind::Xyz { center, extent, resolutions, tile_size } => {
                match k {
                    "center" => *center = opt_point(v)?,
                    "extent" => {
                        *extent = match v {
                            Value::Null => None,
                            Value::Object(em) => {
                                let mut e = Extent::default();
                                e.apply(em)?;
                                Some(e)
                            }
                            _ => return Err(Bad),
                        }
                    }
                    "resolutions" => *resolutions = opt_f64_list(v)?,
                    "tileSize" => *tile_size = opt_i32(v)?,
                    _ => return Ok(false),
                }
                Ok(true)
            }
        }
    }
}

// ---------------------------------------------------------------- dispatch

/// Partial update (or creation from defaults) of any entity of the slice.
pub fn apply_ent(ent: &mut Ent, m: &M) -> PR<()> {
    match ent {
        Ent::User(e) => e.apply(m),
        Ent::Group(e) => e.apply(m),
        Ent::Role(e) => e.apply(m),
        Ent::Layer(e) => e.apply(m),
        Ent::Ds(e) => e.apply(m),
        Ent::App(e) => e.apply(m),
