/// A new entity from a POST body: the Java default constructor, then Jackson.
pub fn new_ent(res: Res, v: &Value) -> PR<Ent> {
    let m = object(v)?;
    let mut ent = match res {
        Res::Users => Ent::User(User::default()),
        Res::Groups => Ent::Group(UserGroup::default()),
        Res::Roles => Ent::Role(Role::default()),
        Res::Layers => Ent::Layer(Layer::default()),
        // LayerDataSource is abstract: Jackson cannot instantiate it.
        Res::DataSources => return Err(Bad),
        Res::Appearances => Ent::App(Appearance::default()),
    };
