tool_use_result.content:
//! Jackson-like reading of a JSON object into the entity model.
//!
//! `apply` is what `ObjectMapper.readerForUpdating(entity).readValue(json)`
//! does: keys present in the JSON are set, others keep their value, unknown
//! keys fail, and `@JsonIgnore`d keys are skipped. Nested objects are always
//! new instances, as Jackson creates them, and sets drop equal duplicates the
//! way `HashSet` does.

use chrono::NaiveDate;
use serde_json::{Map, Value};

use crate::model::*;

/// Any Jackson failure. The handlers decide which status it becomes.
#[derive(Debug)]
pub struct Bad;

pub type PR<T> = Result<T, Bad>;
type M = Map<String, Value>;

pub fn object(v: &Value) -> PR<&M> {
    v.as_object().ok_or(Bad)
}

pub fn opt_string(v: &Value) -> PR<Option<String>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => Ok(Some(s.clone())),
        Value::Number(n) => Ok(Some(n.to_string())),
        Value::Bool(b) => Ok(Some(b.to_string())),
        _ => Err(Bad),
    }
}

pub fn opt_i32(v: &Value) -> PR<Option<i32>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => {
            let i = if let Some(i) = n.as_i64() {
                i
            } else {
                let f = n.as_f64().ok_or(Bad)?;
                if !f.is_finite() || f.abs() > i32::MAX as f64 + 1.0 {
                    return Err(Bad);
                }
                f.trunc() as i64
            };
            i32::try_from(i).map(Some).map_err(|_| Bad)
        }
        Value::String(s) => s.trim().parse::<i32>().map(Some).map_err(|_| Bad),
        _ => Err(Bad),
    }
}

pub fn prim_i32(v: &Value) -> PR<i32> {
    Ok(opt_i32(v)?.unwrap_or(0))
}

pub fn opt_f64(v: &Value) -> PR<Option<f64>> {
    match v {
        Value::Null => Ok(None),
        Value::Number(n) => Ok(Some(n.as_f64().ok_or(Bad)?)),
        Value::String(s) => s.trim().parse::<f64>().map(Some).map_err(|_| Bad),
        _ => Err(Bad),
    }
}

pub fn opt_bool(v: &Value) -> PR<Option<bool>> {
    match v {
        Value::Null => Ok(None),
        Value::Bool(b) => Ok(Some(*b)),
        Value::Number(n) => Ok(Some(n.as_f64().unwrap_or(0.0) != 0.0)),
        Value::String(s) => match s.to_ascii_lowercase().as_str() {
            "true" => Ok(Some(true)),
            "false" => Ok(Some(false)),
            _ => Err(Bad),
        },
        _ => Err(Bad),
    }
}

pub fn prim_bool(v: &Value) -> PR<bool> {
    Ok(opt_bool(v)?.unwrap_or(false))
}

fn opt_date(v: &Value) -> PR<Option<NaiveDate>> {
    match v {
        Value::Null => Ok(None),
        Value::String(s) => NaiveDate::parse_from_str(s.trim(), "%Y-%m-%d").map(Some).map_err(|_| Bad),
        _ => Err(Bad),
    }
}

fn opt_point(v: &Value) -> PR<Option<Point>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => Ok(Some(Point {
            x: prim_f64(m.get("x").unwrap_or(&Value::Null))?,
            y: prim_f64(m.get("y").unwrap_or(&Value::Null))?,
        })),
        _ => Err(Bad),
    }
}

fn prim_f64(v: &Value) -> PR<f64> {
    Ok(opt_f64(v)?.unwrap_or(0.0))
}

fn opt_list<T>(v: &Value, mut f: impl FnMut(&Value) -> PR<T>) -> PR<Option<Vec<T>>> {
    match v {
        Value::Null => Ok(None),
        Value::Array(items) => {
            let mut out = Vec::with_capacity(items.len());
            for it in items {
                out.push(f(it)?);
            }
            Ok(Some(out))
        }
        _ => Err(Bad),
    }
}

fn opt_str_list(v: &Value) -> PR<Option<Vec<String>>> {
    opt_list(v, |x| match x {
        Value::String(s) => Ok(s.clone()),
        Value::Number(n) => Ok(n.to_string()),
        _ => Err(Bad),
    })
}

fn opt_f64_list(v: &Value) -> PR<Option<Vec<f64>>> {
    opt_list(v, |x| opt_f64(x)?.ok_or(Bad))
}

fn ignored(k: &str) -> bool {
    matches!(k, "created" | "modified" | "userPermissions" | "groupPermissions")
}

// ---------------------------------------------------------------- Extent

impl Extent {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "lowerLeft" => self.lower_left = opt_point(v)?,
                "upperRight" => self.upper_right = opt_point(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn extent_from(v: &Value) -> PR<Option<Extent>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => {
            let mut e = Extent::default();
            e.apply(m)?;
            e.cascade = true;
            Ok(Some(e))
        }
        _ => Err(Bad),
    }
}

// ---------------------------------------------------------------- TileGrid

impl TileGrid {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "type" => self.tile_type = opt_string(v)?,
                "tileGridOrigin" => self.origin = opt_point(v)?,
                "tileGridExtent" => self.extent = extent_from(v)?,
                "tileSize" => self.tile_size = opt_i32(v)?,
                "tileGridResolutions" => self.resolutions = opt_f64_list(v)?,
                "matrixIds" if self.wmts => self.matrix_ids = opt_str_list(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn tilegrid_from(v: &Value, wmts: bool) -> PR<Option<TileGrid>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => {
            let mut t = if wmts { TileGrid::wmts_default() } else { TileGrid::default() };
            t.apply(m)?;
            t.cascade = true;
            Ok(Some(t))
        }
        _ => Err(Bad),
    }
}

// ---------------------------------------------------------------- Appearance

impl Appearance {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "attribution" => self.attribution = opt_string(v)?,
                "hoverable" => self.hoverable = opt_bool(v)?,
                "clickable" => self.clickable = opt_bool(v)?,
                "hoverTemplate" => self.hover_template = opt_string(v)?,
                "properties" => {
                    self.properties = match v {
                        Value::Null => None,
                        Value::Object(pm) => {
                            Some(pm.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
                        }
                        _ => return Err(Bad),
                    }
                }
                "name" => self.name = opt_string(v)?,
                "maxResolution" => self.max_resolution = opt_f64(v)?,
                "minResolution" => self.min_resolution = opt_f64(v)?,
                "opacity" => self.opacity = opt_f64(v)?,
                "visible" => self.visible = opt_bool(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn appearance_from(v: &Value) -> PR<Option<Appearance>> {
    match v {
        Value::Null => Ok(None),
        Value::Object(m) => {
            let mut a = Appearance::default();
            a.apply(m)?;
            a.cascade = true;
            Ok(Some(a))
        }
        _ => Err(Bad),
    }
}

// ---------------------------------------------------------------- Role

impl Role {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "name" => self.name = opt_string(v)?,
                "description" => self.description = opt_string(v)?,
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn role_from(v: &Value) -> PR<Role> {
    let mut r = Role::default();
    r.apply(object(v)?)?;
    Ok(r)
}

// ---------------------------------------------------------------- User

fn group_ref(v: &Value) -> PR<i32> {
    match v {
        Value::Number(_) | Value::String(_) => opt_i32(v)?.ok_or(Bad),
        Value::Object(m) => opt_i32(m.get("id").unwrap_or(&Value::Null))?.ok_or(Bad),
        _ => Err(Bad),
    }
}

impl User {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "firstName" => self.first_name = opt_string(v)?,
                "lastName" => self.last_name = opt_string(v)?,
                "email" => self.email = opt_string(v)?,
                "birthday" => self.birthday = opt_date(v)?,
                "language" => self.language = opt_string(v)?,
                "accountName" => self.account_name = opt_string(v)?,
                "password" => self.password = opt_string(v)?,
                "active" => self.active = prim_bool(v)?,
                "roles" => {
                    self.roles = opt_list(v, role_from)?.map(|r| dedupe(r, role_eq));
                }
                "userGroups" => {
                    self.user_groups = opt_list(v, group_ref)?.map(|ids| {
                        dedupe(ids, |a, b| a == b)
                    });
                }
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

fn user_from(v: &Value) -> PR<User> {
    let mut u = User::default();
    u.apply(object(v)?)?;
    Ok(u)
}

fn opt_user_from(v: &Value) -> PR<Option<User>> {
    match v {
        Value::Null => Ok(None),
        _ => user_from(v).map(Some),
    }
}

// ---------------------------------------------------------------- UserGroup

impl UserGroup {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "name" => self.name = opt_string(v)?,
                "owner" => self.owner = opt_user_from(v)?,
                "members" => {
                    self.members = opt_list(v, user_from)?.map(|u| dedupe(u, user_eq));
                }
                "roles" => {
                    self.roles = opt_list(v, role_from)?.map(|r| dedupe(r, role_eq));
                }
                k if ignored(k) => {}
                _ => return Err(Bad),
            }
        }
        Ok(())
    }
}

// ---------------------------------------------------------------- Layer

impl Layer {
    pub fn apply(&mut self, m: &M) -> PR<()> {
        for (k, v) in m {
            match k.as_str() {
                "id" => self.id = opt_i32(v)?,
                "name" => self.name = opt_string(v)?,
                "description" => self.description = opt_string(v)?,
                // LayerDataSource is abstract: Jackson cannot build one.
                "source" => match v {
                    Value::Null => self.source = None,
                    _ => return Err(Bad),
