                    "projection" => *projection = opt_string(v)?,
                    "matrixSet" => *matrix_set = opt_string(v)?,
                    "requestEncoding" => *request_encoding = opt_string(v)?,
                    "capabilitiesUrl" => *capabilities_url = opt_string(v)?,
