    fn equal_nested_roles_are_deduplicated() {
        let mut u = User::default();
        u.apply(object(&json!({"roles": [{"id": 1}, {"id": 2}]})).unwrap()).unwrap();
        // both are built within the same millisecond with the same content
        assert_eq!(u.roles.unwrap().len(), 1);
    }

    #[test]
    fn abstract_source_is_refused_but_null_is_fine() {
        let mut l = Layer::default();
        assert!(l.apply(object(&json!({"source": {"id": 1}})).unwrap()).is_err());
        assert!(l.apply(object(&json!({"source": null})).unwrap()).is_ok());
    }

    #[test]
    fn datasource_kind_keys_are_checked_per_subclass() {
        let mut ds = DataSource {
            id: Some(1),
            created: 0,
            name: None,
            ds_type: None,
            url: None,
            format: None,
            kind: DsKind::ImageWms(ImageFields::empty()),
        };
        assert!(ds.apply(object(&json!({"width": 5})).unwrap()).is_ok());
        assert!(ds.apply(object(&json!({"tileGrid": null})).unwrap()).is_err());
    }
}

