//! join tables give the collections, and cascaded objects are loaded eagerly.

use chrono::NaiveDateTime;
use sqlx::{PgConnection, Row};

use crate::javaish::property_from_db;
use crate::model::*;

pub type DbResult<T> = Result<T, sqlx::Error>;

fn ms(t: Option<NaiveDateTime>) -> i64 {
    t.map(|d| d.and_utc().timestamp_millis()).unwrap_or(0)
}

fn point(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    match (x, y) {
        (None, None) => None,
        (x, y) => Some(Point { x: x.unwrap_or(0.0), y: y.unwrap_or(0.0) }),
    }
}

/// Decodes one `XYZLAYERDATASRC_RESOLUTION.RESOLUTION` value: a Java
/// serialised `Double`, whose value is the last eight bytes.
pub fn decode_java_double(b: &[u8]) -> Option<f64> {
    if b.len() < 8 {
        return None;
    }
    let mut arr = [0u8; 8];
    arr.copy_from_slice(&b[b.len() - 8..]);
    Some(f64::from_be_bytes(arr))
}

/// The Java serialisation prefix of a `java.lang.Double`, followed by the value.
pub fn encode_java_double(d: f64) -> Vec<u8> {
    const PREFIX: &[u8] = &[
        0xAC, 0xED, 0x00, 0x05, 0x73, 0x72, 0x00, 0x10, 0x6A, 0x61, 0x76, 0x61, 0x2E, 0x6C, 0x61, 0x6E,
        0x67, 0x2E, 0x44, 0x6F, 0x75, 0x62, 0x6C, 0x65, 0x80, 0xB3, 0xC2, 0x4A, 0x6B, 0x29, 0xFB, 0x04,
        0x02, 0x00, 0x01, 0x44, 0x00, 0x05, 0x76, 0x61, 0x6C, 0x75, 0x65, 0x78, 0x70,
