pub async fn all_ids(c: &mut PgConnection, table: &str) -> DbResult<Vec<i32>> {
    let rows = sqlx::query(&format!("SELECT id FROM {} ORDER BY id", table))
        .fetch_all(&mut *c)
        .await?;
    rows.iter().map(|r| r.try_get::<i32, _>("id")).collect()
}

pub async fn load_role(c: &mut PgConnection, id: i32) -> DbResult<Option<Role>> {
    let row = sqlx::query("SELECT created, description, name FROM roles WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    Ok(row.map(|r| Role {
        id: Some(id),
        created: ms(r.get("created")),
        name: r.get("name"),
        description: r.get("description"),
    }))
}

pub async fn load_user(c: &mut PgConnection, id: i32) -> DbResult<Option<User>> {
    let row = sqlx::query(
        "SELECT p.created, p.birthday, p.email, p.firstname, p.language, p.lastname, \
         u.accountname, u.active, u.password \
         FROM users u JOIN persons p ON p.id = u.id WHERE u.id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let r = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let role_rows = sqlx::query(
        "SELECT r.id, r.created, r.description, r.name FROM users_roles ur \
         JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1 ORDER BY r.id",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?;
    let roles = role_rows
        .iter()
        .map(|x| Role {
            id: Some(x.get("id")),
            created: ms(x.get("created")),
            name: x.get("name"),
            description: x.get("description"),
        })
        .collect();
    let group_ids: Vec<i32> = sqlx::query("SELECT usergroup_id FROM user_usergroup WHERE user_id = $1 ORDER BY usergroup_id")
        .bind(id)
        .fetch_all(&mut *c)
        .await?
        .iter()
        .map(|x| x.get("usergroup_id"))
        .collect();
    Ok(Some(User {
        id: Some(id),
        created: ms(r.get("created")),
        first_name: r.get("firstname"),
        last_name: r.get("lastname"),
        email: r.get("email"),
        birthday: r.get("birthday"),
        language: r.get("language"),
        account_name: r.get("accountname"),
        password: r.get("password"),
        active: r.get::<Option<bool>, _>("active").unwrap_or(false),
        roles: Some(roles),
        user_groups: Some(group_ids),
    }))
}

pub async fn load_group(c: &mut PgConnection, id: i32) -> DbResult<Option<UserGroup>> {
    let row = sqlx::query("SELECT created, name, owner_id FROM usergroups WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    let r = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let owner_id: Option<i32> = r.get("owner_id");
    let owner = match owner_id {
        Some(oid) => load_user(c, oid).await?,
        None => None,
    };
    let member_ids: Vec<i32> = sqlx::query("SELECT user_id FROM user_usergroup WHERE usergroup_id = $1 ORDER BY user_id")
        .bind(id)
        .fetch_all(&mut *c)
        .await?
        .iter()
        .map(|x| x.get("user_id"))
        .collect();
    let mut members = Vec::with_capacity(member_ids.len());
    for mid in member_ids {
        if let Some(u) = load_user(c, mid).await? {
            members.push(u);
        }
    }
    let role_rows = sqlx::query(
        "SELECT r.id, r.created, r.description, r.name FROM usergroups_roles ugr \
         JOIN roles r ON r.id = ugr.role_id WHERE ugr.usergroup_id = $1 ORDER BY r.id",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?;
    let roles = role_rows
        .iter()
        .map(|x| Role {
            id: Some(x.get("id")),
            created: ms(x.get("created")),
            name: x.get("name"),
            description: x.get("description"),
        })
        .collect();
    Ok(Some(UserGroup {
        id: Some(id),
        created: ms(r.get("created")),
        name: r.get("name"),
        owner,
        members: Some(members),
        roles: Some(roles),
    }))
}

pub async fn load_extent(c: &mut PgConnection, id: i32) -> DbResult<Option<Extent>> {
    let row = sqlx::query(
        "SELECT created, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    Ok(row.map(|r| Extent {
        id: Some(id),
        created: ms(r.get("created")),
        lower_left: point(r.get("lowerleft_x"), r.get("lowerleft_y")),
        upper_right: point(r.get("upperright_x"), r.get("upperright_y")),
        cascade: false,
    }))
}

pub async fn load_tilegrid(c: &mut PgConnection, id: i32) -> DbResult<Option<TileGrid>> {
    let row = sqlx::query(
        "SELECT created, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id \
         FROM tilegrids WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let r = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let wmts: bool = sqlx::query("SELECT EXISTS(SELECT 1 FROM wmtstilegrids WHERE id = $1) AS e")
        .bind(id)
        .fetch_one(&mut *c)
        .await?
        .get("e");
    let resolutions: Vec<f64> = sqlx::query(
        "SELECT resolution FROM tilegrid_resolution WHERE tilegrid_id = $1 ORDER BY idx",
    )
    .bind(id)
    .fetch_all(&mut *c)
    .await?
    .iter()
    .filter_map(|x| x.get::<Option<f64>, _>("resolution"))
    .collect();
    let matrix_ids = if wmts {
        let ids: Vec<String> = sqlx::query("SELECT matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1")
            .bind(id)
            .fetch_all(&mut *c)
            .await?
            .iter()
            .filter_map(|x| x.get::<Option<String>, _>("matrixids"))
            .collect();
        Some(ids)
    } else {
        None
    };
    let extent = match r.get::<Option<i32>, _>("tilegridextent_id") {
        Some(eid) => load_extent(c, eid).await?,
        None => None,
    };
    Ok(Some(TileGrid {
        id: Some(id),
        created: ms(r.get("created")),
        wmts,
        tile_type: r.get("type"),
        origin: point(r.get("tilegridorigin_x"), r.get("tilegridorigin_y")),
        extent,
        tile_size: r.get("tilesize"),
        resolutions: Some(resolutions),
        matrix_ids,
        cascade: false,
        cascade_extent: false,
    }))
}

pub async fn load_appearance(c: &mut PgConnection, id: i32) -> DbResult<Option<Appearance>> {
    let row = sqlx::query(
        "SELECT created, attribution, clickable, hovertemplate, hoverable, maxresolution, \
         minresolution, name, opacity, visible FROM layerappearances WHERE id = $1",
    )
    .bind(id)
    .fetch_optional(&mut *c)
    .await?;
    let r = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let props = sqlx::query("SELECT property, value FROM layerappearances_properties WHERE appearance_id = $1")
        .bind(id)
        .fetch_all(&mut *c)
        .await?
        .iter()
        .map(|x| {
            let key: String = x.get("property");
            let value: Option<String> = x.get("value");
            let v = match value {
                Some(s) => property_from_db(&s),
                None => serde_json::Value::Null,
            };
            (key, v)
        })
        .collect();
    Ok(Some(Appearance {
        id: Some(id),
        created: ms(r.get("created")),
        attribution: r.get("attribution"),
        hoverable: r.get("hoverable"),
        clickable: r.get("clickable"),
        hover_template: r.get("hovertemplate"),
        properties: Some(props),
        name: r.get("name"),
        max_resolution: r.get("maxresolution"),
        min_resolution: r.get("minresolution"),
        opacity: r.get("opacity"),
        visible: r.get("visible"),
        cascade: false,
    }))
}

async fn load_image_fields(c: &mut PgConnection, id: i32) -> DbResult<ImageFields> {
    let r = sqlx::query(
        "SELECT customrequestpath, height, layernames, layerstyles, requestablebypath, version, width \
         FROM imagewmslayerdatasources WHERE id = $1",
    )
    .bind(id)
    .fetch_one(&mut *c)
    .await?;
    Ok(ImageFields {
        width: r.get::<Option<i32>, _>("width").unwrap_or(0),
        height: r.get::<Option<i32>, _>("height").unwrap_or(0),
        version: r.get("version"),
        layer_names: r.get("layernames"),
        layer_styles: r.get("layerstyles"),
        requestable_by_path: r.get("requestablebypath"),
        custom_request_path: r.get("customrequestpath"),
    })
}

pub async fn load_datasource(c: &mut PgConnection, id: i32) -> DbResult<Option<DataSource>> {
    let row = sqlx::query("SELECT created, format, name, type, url FROM layerdatasources WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    let r = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let flags = sqlx::query(
        "SELECT EXISTS(SELECT 1 FROM tilewmslayerdatasources WHERE id = $1) AS tw, \
         EXISTS(SELECT 1 FROM imagewmslayerdatasources WHERE id = $1) AS im, \
         EXISTS(SELECT 1 FROM wfslayerdatasources WHERE id = $1) AS wfs, \
         EXISTS(SELECT 1 FROM wmtslayerdatasources WHERE id = $1) AS wmts, \
         EXISTS(SELECT 1 FROM xyzlayerdatasources WHERE id = $1) AS xyz",
    )
    .bind(id)
    .fetch_one(&mut *c)
    .await?;
    let tw: bool = flags.get("tw");
    let im: bool = flags.get("im");
    let wfs: bool = flags.get("wfs");
    let wmts: bool = flags.get("wmts");
    let xyz: bool = flags.get("xyz");

    let kind = if tw {
        let t = sqlx::query("SELECT request_with_tiled, tilegrid_id FROM tilewmslayerdatasources WHERE id = $1")
            .bind(id)
            .fetch_one(&mut *c)
            .await?;
        let tile_grid = match t.get::<Option<i32>, _>("tilegrid_id") {
            Some(tg) => load_tilegrid(c, tg).await?,
            None => None,
        };
        DsKind::TileWms {
            img: load_image_fields(c, id).await?,
            tile_grid,
            request_with_tiled: t.get("request_with_tiled"),
        }
    } else if im {
        DsKind::ImageWms(load_image_fields(c, id).await?)
    } else if wfs {
        let w = sqlx::query("SELECT typename, typenames, version FROM wfslayerdatasources WHERE id = $1")
            .bind(id)
            .fetch_one(&mut *c)
            .await?;
        DsKind::Wfs {
            version: w.get("version"),
            type_name: w.get("typename"),
            type_names: w.get("typenames"),
        }
    } else if wmts {
        let w = sqlx::query(
            "SELECT capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
             FROM wmtslayerdatasources WHERE id = $1",
        )
        .bind(id)
        .fetch_one(&mut *c)
        .await?;
        let tile_grid = match w.get::<Option<i32>, _>("tilegrid_id") {
            Some(tg) => load_tilegrid(c, tg).await?,
            None => None,
        };
        let urls: Vec<String> = sqlx::query("SELECT urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1")
            .bind(id)
            .fetch_all(&mut *c)
            .await?
            .iter()
            .filter_map(|x| x.get::<Option<String>, _>("urls"))
            .collect();
        DsKind::Wmts {
            tile_grid,
            urls: Some(urls),
            wmts_layer: w.get("wmtslayer"),
            wmts_style: w.get("wmtsstyle"),
            projection: w.get("projection"),
            matrix_set: w.get("matrixset"),
            request_encoding: w.get("requestencoding"),
            capabilities_url: w.get("capabilitiesurl"),
        }
    } else if xyz {
        let x = sqlx::query("SELECT center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources WHERE id = $1")
            .bind(id)
            .fetch_one(&mut *c)
            .await?;
        let resolutions: Vec<f64> = sqlx::query(
            "SELECT resolution FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1 ORDER BY idx",
        )
        .bind(id)
        .fetch_all(&mut *c)
        .await?
        .iter()
        .filter_map(|x| x.get::<Option<Vec<u8>>, _>("resolution"))
        .filter_map(|b| decode_java_double(&b))
        .collect();
        let extent = match x.get::<Option<i32>, _>("extent_id") {
            Some(eid) => load_extent(c, eid).await?,
            None => None,
        };
        DsKind::Xyz {
            center: point(x.get("center_x"), x.get("center_y")),
            extent,
            resolutions: Some(resolutions),
            tile_size: x.get("tilesize"),
        }
    } else {
        // a LayerDataSource row without a subclass row: the original cannot build it
        return Err(sqlx::Error::Protocol(format!("layer data source {} has no subclass", id)));
    };

    Ok(Some(DataSource {
        id: Some(id),
        created: ms(r.get("created")),
        name: r.get("name"),
        ds_type: r.get("type"),
        url: r.get("url"),
        format: r.get("format"),
        kind,
    }))
}

pub async fn load_layer(c: &mut PgConnection, id: i32) -> DbResult<Option<Layer>> {
    let row = sqlx::query("SELECT created, description, name, appearance_id, source_id FROM layers WHERE id = $1")
        .bind(id)
        .fetch_optional(&mut *c)
        .await?;
    let r = match row {
        Some(r) => r,
        None => return Ok(None),
    };
    let source = match r.get::<Option<i32>, _>("source_id") {
        Some(sid) => load_datasource(c, sid).await?,
        None => None,
    };
    let appearance = match r.get::<Option<i32>, _>("appearance_id") {
        Some(aid) => load_appearance(c, aid).await?,
        None => None,
    };
    Ok(Some(Layer {
        id: Some(id),
        created: ms(r.get("created")),
        name: r.get("name"),
        description: r.get("description"),
        source,
        appearance,
    }))
}

/// Loads any entity of the slice by id.
pub async fn load_ent(c: &mut PgConnection, res: Res, id: i32) -> DbResult<Option<Ent>> {
    Ok(match res {
        Res::Users => load_user(c, id).await?.map(Ent::User),
        Res::Groups => load_group(c, id).await?.map(Ent::Group),
        Res::Roles => load_role(c, id).await?.map(Ent::Role),
        Res::Layers => load_layer(c, id).await?.map(Ent::Layer),
        Res::DataSources => load_datasource(c, id).await?.map(Ent::Ds),
        Res::Appearances => load_appearance(c, id).await?.map(Ent::App),
    })
}

pub fn table_of(res: Res) -> &'static str {
    match res {
        Res::Users => "users",
        Res::Groups => "usergroups",
        Res::Roles => "roles",
        Res::Layers => "layers",
        Res::DataSources => "layerdatasources",
        Res::Appearances => "layerappearances",
    }
}

