//! Entity permissions, after `ShogunCorePermissionEvaluator`, the
//! `EntityPermissionEvaluatorFactory` choice of evaluator per class, and the
//! `PersistentObjectPermissionEvaluator` rules on the permission maps.

use sqlx::{PgConnection, Row};

use crate::db::DbResult;
use crate::model::Res;

/// The authenticated principal, loaded for this request.
#[derive(Clone, Debug)]
pub struct Principal {
    pub user_id: i32,
    /// Has `ROLE_ADMIN` (the super admin role: allowed everything).
    pub admin: bool,
    /// Groups the user is a member of.
    pub group_ids: Vec<i32>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Perm {
    Read,
    Create,
    Update,
    Delete,
}

impl Perm {
    fn name(self) -> &'static str {
        match self {
            Perm::Read => "READ",
            Perm::Create => "CREATE",
            Perm::Update => "UPDATE",
            Perm::Delete => "DELETE",
        }
    }
}

/// What a permission is asked about.
#[derive(Clone, Copy, Debug)]
pub enum Target {
    /// A stored entity with its id.
    Stored(i32),
