//! HTTP Basic authentication against the `users` table, as the original's
//! `ShogunCoreAuthenticationProvider` and the `/rest/**` security chain do.

use std::collections::HashMap;
use std::sync::Mutex;

use axum::http::{HeaderMap, StatusCode};
use base64::Engine;
use sqlx::{PgPool, Row};

use crate::model::{ROLE_ADMIN, ROLE_USER};
use crate::perm::Principal;

/// Passwords verified before, keyed by account and raw password, holding the
/// stored hash they matched. bcrypt at cost 10 is slow; the hash is re-checked.
static VERIFIED: Mutex<Option<HashMap<String, String>>> = Mutex::new(None);

fn remember(key: String, stored: String) {
    let mut guard = VERIFIED.lock().unwrap_or_else(|e| e.into_inner());
    guard.get_or_insert_with(HashMap::new).insert(key, stored);
}

fn known_good(key: &str, stored: &str) -> bool {
    let guard = VERIFIED.lock().unwrap_or_else(|e| e.into_inner());
    guard.as_ref().and_then(|m| m.get(key)).map(|s| s == stored).unwrap_or(false)
}

/// Spring's `BCryptPasswordEncoder.matches`: a stored value that is not a
/// bcrypt hash never matches.
async fn bcrypt_matches(account: &str, raw: &str, stored: &str) -> bool {
    let key = format!("{}\u{0}{}", account, raw);
    if known_good(&key, stored) {
        return true;
    }
    let raw_owned = raw.to_string();
    let stored_owned = stored.to_string();
    let ok = tokio::task::spawn_blocking(move || bcrypt::verify(&raw_owned, &stored_owned).unwrap_or(false))
        .await
        .unwrap_or(false);
    if ok {
        remember(key, stored.to_string());
    }
    ok
}

/// Why a request is refused before reaching a controller.
pub enum AuthFail {
    /// Spring's Basic entry point: no or wrong credentials, or no authority.
    Unauthorized,
    /// Authenticated, but none of the roles the `/rest` chain requires.
    Forbidden,
    Db,
}

impl AuthFail {
    pub fn status(&self) -> StatusCode {
        match self {
            AuthFail::Unauthorized => StatusCode::UNAUTHORIZED,
            AuthFail::Forbidden => StatusCode::FORBIDDEN,
            AuthFail::Db => StatusCode::INTERNAL_SERVER_ERROR,
        }
    }
}

fn basic_credentials(headers: &HeaderMap) -> Option<(String, String)> {
    let value = headers.get(axum::http::header::AUTHORIZATION)?.to_str().ok()?;
    let encoded = value.strip_prefix("Basic ").or_else(|| value.strip_prefix("basic "))?;
    let decoded = base64::engine::general_purpose::STANDARD.decode(encoded.trim()).ok()?;
    let text = String::from_utf8(decoded).ok()?;
    let (user, pass) = text.split_once(':')?;
    Some((user.to_string(), pass.to_string()))
}

pub async fn authenticate(pool: &PgPool, headers: &HeaderMap) -> Result<Principal, AuthFail> {
    let (account, raw) = basic_credentials(headers).ok_or(AuthFail::Unauthorized)?;
    let row = sqlx::query(
        "SELECT u.id, u.password, u.active FROM users u WHERE u.accountname = $1",
    )
    .bind(&account)
    .fetch_optional(pool)
    .await
    .map_err(|_| AuthFail::Db)?;
    let row = row.ok_or(AuthFail::Unauthorized)?;
    let user_id: i32 = row.get("id");
    let active: bool = row.get::<Option<bool>, _>("active").unwrap_or(false);
    if !active {
        return Err(AuthFail::Unauthorized);
    }
    let stored: String = match row.get::<Option<String>, _>("password") {
        Some(s) => s,
        None => return Err(AuthFail::Unauthorized),
    };
    if !bcrypt_matches(&account, &raw, &stored).await {
        return Err(AuthFail::Unauthorized);
    }

    // authorities: the user's roles and the roles of every group the user is in
    let authorities: Vec<String> = sqlx::query(
        "SELECT r.name AS name FROM roles r WHERE r.id IN (\
           SELECT ur.role_id FROM users_roles ur WHERE ur.user_id = $1 \
           UNION \
           SELECT ugr.role_id FROM usergroups_roles ugr \
           JOIN user_usergroup uug ON uug.usergroup_id = ugr.usergroup_id WHERE uug.user_id = $1)",
    )
    .bind(user_id)
    .fetch_all(pool)
    .await
    .map_err(|_| AuthFail::Db)?
    .iter()
    .filter_map(|r| r.get::<Option<String>, _>("name"))
    .collect();
    if authorities.is_empty() {
        return Err(AuthFail::Unauthorized);
    }
    let admin = authorities.iter().any(|a| a == ROLE_ADMIN);
    // the role hierarchy ROLE_ADMIN > ROLE_USER
    if !admin && !authorities.iter().any(|a| a == ROLE_USER) {
        return Err(AuthFail::Forbidden);
    }
    let group_ids: Vec<i32> = sqlx::query("SELECT usergroup_id FROM user_usergroup WHERE user_id = $1")
        .bind(user_id)
        .fetch_all(pool)
        .await
        .map_err(|_| AuthFail::Db)?
        .iter()
        .map(|r| r.get("usergroup_id"))
        .collect();
    Ok(Principal { user_id, admin, group_ids })
}

