//! The generic REST endpoints of `AbstractRestController` for the six
//! resources, with the status codes the original gives for each outcome.

use std::sync::Arc;

use axum::body::Body;
use axum::extract::{Path, RawQuery, State};
use axum::http::{header, HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use serde_json::{Map, Value};
use sqlx::PgPool;

use crate::auth::authenticate;
use crate::db::{all_ids, load_ent, load_group, load_user, DbResult};
use crate::javaish::{cast_bool, cast_double, cast_int, split_commas};
use crate::model::*;
use crate::parse::{apply_ent, new_ent, object};
use crate::perm::{can, Perm, Principal, Target};
use crate::write::{Loaded, Writer};

pub struct AppState {
    pub pool: PgPool,
}

type St = State<Arc<AppState>>;

const OUTPUT_ONLY: &str = "output:only";

fn json_response(status: StatusCode, v: &Value) -> Response {
    let body = serde_json::to_vec(v).unwrap_or_else(|_| b"null".to_vec());
    Response::builder()
        .status(status)
        .header(header::CONTENT_TYPE, "application/json;charset=UTF-8")
        .body(Body::from(body))
        .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}

fn status_only(status: StatusCode) -> Response {
    status.into_response()
}

fn parse_query(q: Option<&str>) -> Vec<(String, String)> {
    match q {
        Some(q) => form_urlencoded::parse(q.as_bytes())
            .map(|(k, v)| (k.into_owned(), v.into_owned()))
            .collect(),
        None => Vec::new(),
    }
}

/// `EntityUtil.determineRestrictFields`: the scalar fields `output:only` names.
fn restrict_fields(params: &[(String, String)], res: Res) -> Option<Vec<String>> {
    // the values of the last key that equals "output:only" ignoring case
    let mut requested: Option<Vec<String>> = None;
    let mut seen_keys: Vec<&str> = Vec::new();
    for (k, _) in params {
        if k.eq_ignore_ascii_case(OUTPUT_ONLY) && !seen_keys.contains(&k.as_str()) {
            seen_keys.push(k.as_str());
        }
    }
    if let Some(last) = seen_keys.last() {
        let mut values: Vec<String> = Vec::new();
        for (k, v) in params {
            if k == last {
                values.extend(split_commas(v));
            }
        }
        requested = Some(values);
    }
    let requested = requested?;
    if requested.is_empty() {
        return None;
    }
    let fields: Vec<String> = res
        .scalar_fields()
        .iter()
        .filter(|(name, _)| requested.iter().any(|r| r.eq_ignore_ascii_case(name)))
        .map(|(name, _)| name.to_string())
        .collect();
    if fields.is_empty() {
        None
    } else {
        Some(fields)
    }
}

enum CritValue {
    Str(String),
    Int(i32),
    Bool(bool),
    Dbl(f64),
}

/// `findBySimpleFilter`: per field, the values are OR-ed; the fields AND-ed.
/// `None` when no request parameter names a filterable field (the original
/// then returns an empty list without querying).
fn filter_criteria(params: &[(String, String)], res: Res) -> Option<Vec<(&'static str, Vec<CritValue>)>> {
    let mut out: Vec<(&'static str, Vec<CritValue>)> = Vec::new();
    for (name, kind) in res.scalar_fields() {
        let mut values: Vec<CritValue> = Vec::new();
        for (k, v) in params {
            // the output:only key is removed before the filter is built
            if k == OUTPUT_ONLY || !k.eq_ignore_ascii_case(name) {
                continue;
            }
            values.push(match kind {
                FieldKind::Str => CritValue::Str(v.clone()),
                FieldKind::Int => CritValue::Int(cast_int(v)),
                FieldKind::Bool => CritValue::Bool(cast_bool(v)),
                FieldKind::Dbl => CritValue::Dbl(cast_double(v)),
            });
        }
        if !values.is_empty() {
            out.push((name, values));
        }
    }
    if out.is_empty() {
        None
    } else {
        Some(out)
    }
}

fn matches_filter(json: &Value, criteria: &[(&'static str, Vec<CritValue>)]) -> bool {
    criteria.iter().all(|(field, values)| {
        let v = json.get(*field);
        values.iter().any(|c| match (c, v) {
            (CritValue::Str(s), Some(Value::String(x))) => s == x,
            (CritValue::Int(i), Some(Value::Number(n))) => n.as_i64() == Some(*i as i64),
            (CritValue::Bool(b), Some(Value::Bool(x))) => b == x,
            (CritValue::Dbl(d), Some(Value::Number(n))) => n.as_f64() == Some(*d),
            _ => false,
        })
    })
}

/// `Jackson JsonNode.asInt()` as the update endpoint uses it for the payload id.
fn node_as_int(v: &Value) -> i32 {
    match v {
        Value::Number(n) => match n.as_i64() {
            Some(i) => i as i32,
            None => n.as_f64().map(|f| f as i32).unwrap_or(0),
        },
        Value::String(s) => s.trim().parse::<i32>().unwrap_or(0),
        Value::Bool(b) => *b as i32,
        _ => 0,
    }
}

/// The entities a Hibernate session would hold for an entity loaded for update.
fn loaded_graph(e: &Ent) -> Loaded {
    fn tile_grid(l: &mut Loaded, t: &TileGrid) {
        l.insert("TileGrid", t.id);
        if let Some(x) = &t.extent {
            l.insert("Extent", x.id);
        }
    }
    fn source(l: &mut Loaded, d: &DataSource) {
        l.insert("DataSource", d.id);
        match &d.kind {
            DsKind::TileWms { tile_grid: Some(t), .. } | DsKind::Wmts { tile_grid: Some(t), .. } => tile_grid(l, t),
            DsKind::Xyz { extent: Some(x), .. } => l.insert("Extent", x.id),
            _ => {}
        }
    }
    let mut l = Loaded::default();
    match e {
        Ent::Layer(layer) => {
            l.insert("Layer", layer.id);
            if let Some(a) = &layer.appearance {
                l.insert("Appearance", a.id);
            }
            if let Some(s) = &layer.source {
                source(&mut l, s);
            }
        }
        Ent::Ds(d) => source(&mut l, d),
        Ent::App(a) => l.insert("Appearance", a.id),
        _ => {}
    }
    l
}

fn set_ent_id(e: &mut Ent, id: i32) {
    match e {
        Ent::User(x) => x.id = Some(id),
        Ent::Group(x) => x.id = Some(id),
        Ent::Role(x) => x.id = Some(id),
        Ent::Layer(x) => x.id = Some(id),
        Ent::Ds(x) => x.id = Some(id),
        Ent::App(x) => x.id = Some(id),
    }
}

/// Loads an entity the principal may read (`findById`'s PostAuthorize).
async fn read_one(pool: &PgPool, p: &Principal, res: Res, id: i32) -> Result<Option<Ent>, StatusCode> {
    let mut conn = pool.acquire().await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let ent = match load_ent(&mut conn, res, id).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)? {
        Some(e) => e,
        None => return Ok(None),
    };
    if can(&mut conn, p, res, Target::Stored(id), Perm::Read)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
    {
        Ok(Some(ent))
    } else {
        Ok(None)
    }
}

fn parse_id(raw: &str) -> Result<i32, StatusCode> {
    raw.parse::<i32>().map_err(|_| StatusCode::BAD_REQUEST)
}

fn resource(raw: &str) -> Result<Res, StatusCode> {
    Res::parse(raw).ok_or(StatusCode::NOT_FOUND)
}

// ---------------------------------------------------------------- list / filter

async fn list_impl(pool: &PgPool, headers: &HeaderMap, res: Res, query: Option<&str>, filter: bool) -> Response {
    let p = match authenticate(pool, headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    match list_or_filter(pool, &p, res, query, filter).await {
        Ok(arr) => json_response(StatusCode::OK, &Value::Array(arr)),
        Err(s) => status_only(s),
    }
}

async fn list_or_filter(
    pool: &PgPool,
    p: &Principal,
    res: Res,
    query: Option<&str>,
    filter: bool,
) -> Result<Vec<Value>, StatusCode> {
    let params = parse_query(query);
    let restrict = restrict_fields(&params, res);
    let criteria = if filter {
        match filter_criteria(&params, res) {
            Some(c) => Some(c),
            // no filterable parameter: the original returns [] without querying
            None => return Ok(Vec::new()),
        }
    } else {
        None
    };
    let mut conn = pool.acquire().await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let ids = all_ids(&mut conn, crate::db::table_of(res)).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let mut matched: Vec<(i32, Ent, Value)> = Vec::new();
    for id in ids {
        let ent = load_ent(&mut conn, res, id)
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
            .ok_or(StatusCode::INTERNAL_SERVER_ERROR)?;
        let internal = ent.to_json(true);
        if let Some(c) = &criteria {
            if !matches_filter(&internal, c) {
                continue;
            }
        }
        matched.push((id, ent.clone(), ent.to_json(false)));
    }
    // a projection over data sources: Hibernate cannot instantiate the abstract class
    if restrict.is_some() && res == Res::DataSources && !matched.is_empty() {
        return Err(StatusCode::INTERNAL_SERVER_ERROR);
    }
    let mut out = Vec::new();
    for (id, _ent, public) in matched {
        let readable = if p.admin {
            true
        } else {
            match &restrict {
                Some(_) => can(&mut conn, p, res, Target::Detached, Perm::Read).await,
                None => can(&mut conn, p, res, Target::Stored(id), Perm::Read).await,
            }
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        };
        if !readable {
            continue;
        }
        out.push(match &restrict {
            Some(fields) => project(res, &public, fields),
            None => public,
        });
    }
    Ok(out)
}

pub async fn list_h(st: St, Path(res): Path<String>, headers: HeaderMap, RawQuery(q): RawQuery) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    list_impl(&st.pool, &headers, res, q.as_deref(), false).await
}

pub async fn filter_h(st: St, Path(res): Path<String>, headers: HeaderMap, RawQuery(q): RawQuery) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    list_impl(&st.pool, &headers, res, q.as_deref(), true).await
}

// ---------------------------------------------------------------- get

pub async fn get_h(st: St, Path((res, id)): Path<(String, String)>, headers: HeaderMap) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    // any failure while finding the entity is a 404 in the original
    match read_one(&st.pool, &p, res, id).await {
        Ok(Some(ent)) => json_response(StatusCode::OK, &ent.to_json(false)),
        _ => status_only(StatusCode::NOT_FOUND),
    }
}

// ---------------------------------------------------------------- create

pub async fn create_h(st: St, Path(res): Path<String>, headers: HeaderMap, body: axum::body::Bytes) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    // any failure while saving is a 400 in the original
    match create_impl(&st.pool, &p, res, &body).await {
        Ok(v) => json_response(StatusCode::CREATED, &v),
        Err(_) => status_only(StatusCode::BAD_REQUEST),
    }
}

async fn create_impl(pool: &PgPool, p: &Principal, res: Res, body: &[u8]) -> Result<Value, ()> {
    let v: Value = serde_json::from_slice(body).map_err(|_| ())?;
    let mut ent = new_ent(res, &v).map_err(|_| ())?;
    if ent.id().is_some() {
        return Err(());
    }
    let mut conn = pool.acquire().await.map_err(|_| ())?;
    if !can(&mut conn, p, res, Target::Detached, Perm::Create).await.map_err(|_| ())? {
        return Err(());
    }
    drop(conn);
    let mut tx = pool.begin().await.map_err(|_| ())?;
    let writer = Writer { pool, loaded: Loaded::default() };
    writer.save_ent(&mut tx, &mut ent).await.map_err(|_| ())?;
    tx.commit().await.map_err(|_| ())?;
    Ok(ent.to_json(false))
}

// ---------------------------------------------------------------- update

pub async fn update_h(
    st: St,
    Path((res, id)): Path<(String, String)>,
    headers: HeaderMap,
    body: axum::body::Bytes,
) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    match update_impl(&st.pool, &p, res, id, &body).await {
        Ok(v) => json_response(StatusCode::OK, &v),
        Err(s) => status_only(s),
    }
}

async fn update_impl(pool: &PgPool, p: &Principal, res: Res, id: i32, body: &[u8]) -> Result<Value, StatusCode> {
    // a body that is not JSON is an IOException (404); an empty one reads as null
    let v: Value = if body.iter().all(|b| b.is_ascii_whitespace()) {
        Value::Null
    } else {
        serde_json::from_slice(body).map_err(|_| StatusCode::NOT_FOUND)?
    };
    let obj = match v.as_object() {
        Some(o) if o.contains_key("id") => o,
        _ => return Err(StatusCode::BAD_REQUEST),
    };
    if node_as_int(&obj["id"]) != id {
        return Err(StatusCode::BAD_REQUEST);
    }
    let mut ent = read_one(pool, p, res, id)
        .await?
        .ok_or(StatusCode::NOT_FOUND)?;
    let loaded = loaded_graph(&ent);
    if !p.admin {
        let mut conn = pool.acquire().await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
        if !can(&mut conn, p, res, Target::Stored(id), Perm::Update)
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        {
            return Err(StatusCode::NOT_FOUND);
        }
    }
    apply_ent(&mut ent, object(&v).map_err(|_| StatusCode::NOT_FOUND)?).map_err(|_| StatusCode::NOT_FOUND)?;
    let mut tx = pool.begin().await.map_err(|_| StatusCode::NOT_FOUND)?;
    let writer = Writer { pool, loaded };
    writer.save_ent(&mut tx, &mut ent).await.map_err(|_| StatusCode::NOT_FOUND)?;
    tx.commit().await.map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(ent.to_json(false))
}

// ---------------------------------------------------------------- delete

pub async fn delete_h(st: St, Path((res, id)): Path<(String, String)>, headers: HeaderMap) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    match delete_impl(&st.pool, &p, res, id).await {
        Ok(()) => status_only(StatusCode::NO_CONTENT),
        Err(_) => status_only(StatusCode::NOT_FOUND),
    }
}

async fn delete_impl(pool: &PgPool, p: &Principal, res: Res, id: i32) -> Result<(), ()> {
    let ent = read_one(pool, p, res, id).await.map_err(|_| ())?.ok_or(())?;
    {
        let mut conn = pool.acquire().await.map_err(|_| ())?;
        if !can(&mut conn, p, res, Target::Stored(id), Perm::Delete).await.map_err(|_| ())? {
            return Err(());
        }
    }
    let mut tx = pool.begin().await.map_err(|_| ())?;
    let writer = Writer { pool, loaded: Loaded::default() };
    writer.delete_ent(&mut tx, &ent).await.map_err(|_| ())?;
    tx.commit().await.map_err(|_| ())?;
    Ok(())
}

// ---------------------------------------------------------------- relations

/// `GET /users/{id}/userGroups`: the user's groups the principal may read.
pub async fn user_groups_h(st: St, Path((res, id)): Path<(String, String)>, headers: HeaderMap) -> Response {
    if res != "users" {
        return status_only(StatusCode::NOT_FOUND);
    }
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    match related(&st.pool, &p, Res::Users, id).await {
        Ok(v) => json_response(StatusCode::OK, &v),
        Err(_) => status_only(StatusCode::NOT_FOUND),
    }
}

/// `GET /groups/{id}/users`: the group's members the principal may read.
pub async fn group_users_h(st: St, Path((res, id)): Path<(String, String)>, headers: HeaderMap) -> Response {
    if res != "groups" {
        return status_only(StatusCode::NOT_FOUND);
    }
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    match related(&st.pool, &p, Res::Groups, id).await {
        Ok(v) => json_response(StatusCode::OK, &v),
        Err(_) => status_only(StatusCode::NOT_FOUND),
    }
}

/// `getGroupsOfUser` / `getUsersOfGroup`: the owner is looked up without a
/// permission check, the result is filtered by READ.
async fn related(pool: &PgPool, p: &Principal, owner: Res, id: i32) -> Result<Value, ()> {
    let mut conn = pool.acquire().await.map_err(|_| ())?;
    let mut out: Vec<Value> = Vec::new();
    match owner {
        Res::Users => {
            let user = load_user(&mut conn, id).await.map_err(|_| ())?.ok_or(())?;
            for gid in user.user_groups.unwrap_or_default() {
                if let Some(g) = load_group(&mut conn, gid).await.map_err(|_| ())? {
                    if readable(&mut conn, p, Res::Groups, gid).await? {
                        out.push(UserGroup::to_json(&g));
                    }
                }
            }
        }
        Res::Groups => {
            let group = load_group(&mut conn, id).await.map_err(|_| ())?.ok_or(())?;
            for m in group.members.unwrap_or_default() {
                let mid = m.id.ok_or(())?;
                if readable(&mut conn, p, Res::Users, mid).await? {
                    out.push(m.to_json(false));
                }
            }
        }
        _ => return Err(()),
    }
    let _: DbResult<()> = Ok(());
    Ok(Value::Array(out))
}

async fn readable(conn: &mut sqlx::PgConnection, p: &Principal, res: Res, id: i32) -> Result<bool, ()> {
    if p.admin {
        return Ok(true);
    }
    can(conn, p, res, Target::Stored(id), Perm::Read).await.map_err(|_| ())
}

// keep the unused-import lint quiet for helpers referenced only in some builds
#[allow(dead_code)]
fn _unused(_: Map<String, Value>) {}

tool_use_result.content:
//! The generic REST endpoints of `AbstractRestController` for the six
//! resources, with the status codes the original gives for each outcome.

use std::sync::Arc;

use axum::body::Body;
use axum::extract::{Path, RawQuery, State};
use axum::http::{header, HeaderMap, StatusCode};
use axum::response::{IntoResponse, Response};
use serde_json::{Map, Value};
use sqlx::PgPool;

use crate::auth::authenticate;
use crate::db::{all_ids, load_ent, load_group, load_user, DbResult};
use crate::javaish::{cast_bool, cast_double, cast_int, split_commas};
use crate::model::*;
use crate::parse::{apply_ent, new_ent, object};
use crate::perm::{can, Perm, Principal, Target};
use crate::write::{Loaded, Writer};

pub struct AppState {
    pub pool: PgPool,
}

type St = State<Arc<AppState>>;

const OUTPUT_ONLY: &str = "output:only";

fn json_response(status: StatusCode, v: &Value) -> Response {
    let body = serde_json::to_vec(v).unwrap_or_else(|_| b"null".to_vec());
    Response::builder()
        .status(status)
        .header(header::CONTENT_TYPE, "application/json;charset=UTF-8")
        .body(Body::from(body))
        .unwrap_or_else(|_| StatusCode::INTERNAL_SERVER_ERROR.into_response())
}

fn status_only(status: StatusCode) -> Response {
    status.into_response()
}

fn parse_query(q: Option<&str>) -> Vec<(String, String)> {
    match q {
        Some(q) => form_urlencoded::parse(q.as_bytes())
            .map(|(k, v)| (k.into_owned(), v.into_owned()))
            .collect(),
        None => Vec::new(),
    }
}

/// `EntityUtil.determineRestrictFields`: the scalar fields `output:only` names.
fn restrict_fields(params: &[(String, String)], res: Res) -> Option<Vec<String>> {
    // the values of the last key that equals "output:only" ignoring case
    let mut requested: Option<Vec<String>> = None;
    let mut seen_keys: Vec<&str> = Vec::new();
    for (k, _) in params {
        if k.eq_ignore_ascii_case(OUTPUT_ONLY) && !seen_keys.contains(&k.as_str()) {
            seen_keys.push(k.as_str());
        }
    }
    if let Some(last) = seen_keys.last() {
        let mut values: Vec<String> = Vec::new();
        for (k, v) in params {
            if k == last {
                values.extend(split_commas(v));
            }
        }
        requested = Some(values);
    }
    let requested = requested?;
    if requested.is_empty() {
        return None;
    }
    let fields: Vec<String> = res
        .scalar_fields()
        .iter()
        .filter(|(name, _)| requested.iter().any(|r| r.eq_ignore_ascii_case(name)))
        .map(|(name, _)| name.to_string())
        .collect();
    if fields.is_empty() {
        None
    } else {
        Some(fields)
    }
}

enum CritValue {
    Str(String),
    Int(i32),
    Bool(bool),
    Dbl(f64),
}

/// `findBySimpleFilter`: per field, the values are OR-ed; the fields AND-ed.
/// `None` when no request parameter names a filterable field (the original
/// then returns an empty list without querying).
fn filter_criteria(params: &[(String, String)], res: Res) -> Option<Vec<(&'static str, Vec<CritValue>)>> {
    let mut out: Vec<(&'static str, Vec<CritValue>)> = Vec::new();
    for (name, kind) in res.scalar_fields() {
        let mut values: Vec<CritValue> = Vec::new();
        for (k, v) in params {
            // the output:only key is removed before the filter is built
            if k == OUTPUT_ONLY || !k.eq_ignore_ascii_case(name) {
                continue;
            }
            values.push(match kind {
                FieldKind::Str => CritValue::Str(v.clone()),
                FieldKind::Int => CritValue::Int(cast_int(v)),
                FieldKind::Bool => CritValue::Bool(cast_bool(v)),
                FieldKind::Dbl => CritValue::Dbl(cast_double(v)),
            });
        }
        if !values.is_empty() {
            out.push((name, values));
        }
    }
    if out.is_empty() {
        None
    } else {
        Some(out)
    }
}

fn matches_filter(json: &Value, criteria: &[(&'static str, Vec<CritValue>)]) -> bool {
    criteria.iter().all(|(field, values)| {
        let v = json.get(*field);
        values.iter().any(|c| match (c, v) {
            (CritValue::Str(s), Some(Value::String(x))) => s == x,
            (CritValue::Int(i), Some(Value::Number(n))) => n.as_i64() == Some(*i as i64),
            (CritValue::Bool(b), Some(Value::Bool(x))) => b == x,
            (CritValue::Dbl(d), Some(Value::Number(n))) => n.as_f64() == Some(*d),
            _ => false,
        })
    })
}

/// `Jackson JsonNode.asInt()` as the update endpoint uses it for the payload id.
fn node_as_int(v: &Value) -> i32 {
    match v {
        Value::Number(n) => match n.as_i64() {
            Some(i) => i as i32,
            None => n.as_f64().map(|f| f as i32).unwrap_or(0),
        },
        Value::String(s) => s.trim().parse::<i32>().unwrap_or(0),
        Value::Bool(b) => *b as i32,
        _ => 0,
    }
}

/// The entities a Hibernate session would hold for an entity loaded for update.
fn loaded_graph(e: &Ent) -> Loaded {
    fn tile_grid(l: &mut Loaded, t: &TileGrid) {
        l.insert("TileGrid", t.id);
        if let Some(x) = &t.extent {
            l.insert("Extent", x.id);
        }
    }
    fn source(l: &mut Loaded, d: &DataSource) {
        l.insert("DataSource", d.id);
        match &d.kind {
            DsKind::TileWms { tile_grid: Some(t), .. } | DsKind::Wmts { tile_grid: Some(t), .. } => tile_grid(l, t),
            DsKind::Xyz { extent: Some(x), .. } => l.insert("Extent", x.id),
            _ => {}
        }
    }
    let mut l = Loaded::default();
    match e {
        Ent::Layer(layer) => {
            l.insert("Layer", layer.id);
            if let Some(a) = &layer.appearance {
                l.insert("Appearance", a.id);
            }
            if let Some(s) = &layer.source {
                source(&mut l, s);
            }
        }
        Ent::Ds(d) => source(&mut l, d),
        Ent::App(a) => l.insert("Appearance", a.id),
        _ => {}
    }
    l
}

fn set_ent_id(e: &mut Ent, id: i32) {
    match e {
        Ent::User(x) => x.id = Some(id),
        Ent::Group(x) => x.id = Some(id),
        Ent::Role(x) => x.id = Some(id),
        Ent::Layer(x) => x.id = Some(id),
        Ent::Ds(x) => x.id = Some(id),
        Ent::App(x) => x.id = Some(id),
    }
}

/// Loads an entity the principal may read (`findById`'s PostAuthorize).
async fn read_one(pool: &PgPool, p: &Principal, res: Res, id: i32) -> Result<Option<Ent>, StatusCode> {
    let mut conn = pool.acquire().await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let ent = match load_ent(&mut conn, res, id).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)? {
        Some(e) => e,
        None => return Ok(None),
    };
    if can(&mut conn, p, res, Target::Stored(id), Perm::Read)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
    {
        Ok(Some(ent))
    } else {
        Ok(None)
    }
}

fn parse_id(raw: &str) -> Result<i32, StatusCode> {
    raw.parse::<i32>().map_err(|_| StatusCode::BAD_REQUEST)
}

fn resource(raw: &str) -> Result<Res, StatusCode> {
    Res::parse(raw).ok_or(StatusCode::NOT_FOUND)
}

// ---------------------------------------------------------------- list / filter

async fn list_impl(pool: &PgPool, headers: &HeaderMap, res: Res, query: Option<&str>, filter: bool) -> Response {
    let p = match authenticate(pool, headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    match list_or_filter(pool, &p, res, query, filter).await {
        Ok(arr) => json_response(StatusCode::OK, &Value::Array(arr)),
        Err(s) => status_only(s),
    }
}

async fn list_or_filter(
    pool: &PgPool,
    p: &Principal,
    res: Res,
    query: Option<&str>,
    filter: bool,
) -> Result<Vec<Value>, StatusCode> {
    let params = parse_query(query);
    let restrict = restrict_fields(&params, res);
    let criteria = if filter {
        match filter_criteria(&params, res) {
            Some(c) => Some(c),
            // no filterable parameter: the original returns [] without querying
            None => return Ok(Vec::new()),
        }
    } else {
        None
    };
    let mut conn = pool.acquire().await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let ids = all_ids(&mut conn, crate::db::table_of(res)).await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    let mut matched: Vec<(i32, Ent, Value)> = Vec::new();
    for id in ids {
        let ent = load_ent(&mut conn, res, id)
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
            .ok_or(StatusCode::INTERNAL_SERVER_ERROR)?;
        let internal = ent.to_json(true);
        if let Some(c) = &criteria {
            if !matches_filter(&internal, c) {
                continue;
            }
        }
        matched.push((id, ent.clone(), ent.to_json(false)));
    }
    // a projection over data sources: Hibernate cannot instantiate the abstract class
    if restrict.is_some() && res == Res::DataSources && !matched.is_empty() {
        return Err(StatusCode::INTERNAL_SERVER_ERROR);
    }
    let mut out = Vec::new();
    for (id, _ent, public) in matched {
        let readable = if p.admin {
            true
        } else {
            match &restrict {
                Some(_) => can(&mut conn, p, res, Target::Detached, Perm::Read).await,
                None => can(&mut conn, p, res, Target::Stored(id), Perm::Read).await,
            }
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        };
        if !readable {
            continue;
        }
        out.push(match &restrict {
            Some(fields) => project(res, &public, fields),
            None => public,
        });
    }
    Ok(out)
}

pub async fn list_h(st: St, Path(res): Path<String>, headers: HeaderMap, RawQuery(q): RawQuery) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    list_impl(&st.pool, &headers, res, q.as_deref(), false).await
}

pub async fn filter_h(st: St, Path(res): Path<String>, headers: HeaderMap, RawQuery(q): RawQuery) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    list_impl(&st.pool, &headers, res, q.as_deref(), true).await
}

// ---------------------------------------------------------------- get

pub async fn get_h(st: St, Path((res, id)): Path<(String, String)>, headers: HeaderMap) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    // any failure while finding the entity is a 404 in the original
    match read_one(&st.pool, &p, res, id).await {
        Ok(Some(ent)) => json_response(StatusCode::OK, &ent.to_json(false)),
        _ => status_only(StatusCode::NOT_FOUND),
    }
}

// ---------------------------------------------------------------- create

pub async fn create_h(st: St, Path(res): Path<String>, headers: HeaderMap, body: axum::body::Bytes) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    // any failure while saving is a 400 in the original
    match create_impl(&st.pool, &p, res, &body).await {
        Ok(v) => json_response(StatusCode::CREATED, &v),
        Err(_) => status_only(StatusCode::BAD_REQUEST),
    }
}

async fn create_impl(pool: &PgPool, p: &Principal, res: Res, body: &[u8]) -> Result<Value, ()> {
    let v: Value = serde_json::from_slice(body).map_err(|_| ())?;
    let mut ent = new_ent(res, &v).map_err(|_| ())?;
    if ent.id().is_some() {
        return Err(());
    }
    let mut conn = pool.acquire().await.map_err(|_| ())?;
    if !can(&mut conn, p, res, Target::Detached, Perm::Create).await.map_err(|_| ())? {
        return Err(());
    }
    drop(conn);
    let mut tx = pool.begin().await.map_err(|_| ())?;
    let writer = Writer { pool, loaded: Loaded::default() };
    writer.save_ent(&mut tx, &mut ent).await.map_err(|_| ())?;
    tx.commit().await.map_err(|_| ())?;
    Ok(ent.to_json(false))
}

// ---------------------------------------------------------------- update

pub async fn update_h(
    st: St,
    Path((res, id)): Path<(String, String)>,
    headers: HeaderMap,
    body: axum::body::Bytes,
) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    match update_impl(&st.pool, &p, res, id, &body).await {
        Ok(v) => json_response(StatusCode::OK, &v),
        Err(s) => status_only(s),
    }
}

async fn update_impl(pool: &PgPool, p: &Principal, res: Res, id: i32, body: &[u8]) -> Result<Value, StatusCode> {
    // a body that is not JSON is an IOException (404); an empty one reads as null
    let v: Value = if body.iter().all(|b| b.is_ascii_whitespace()) {
        Value::Null
    } else {
        serde_json::from_slice(body).map_err(|_| StatusCode::NOT_FOUND)?
    };
    let obj = match v.as_object() {
        Some(o) if o.contains_key("id") => o,
        _ => return Err(StatusCode::BAD_REQUEST),
    };
    if node_as_int(&obj["id"]) != id {
        return Err(StatusCode::BAD_REQUEST);
    }
    let mut ent = read_one(pool, p, res, id)
        .await?
        .ok_or(StatusCode::NOT_FOUND)?;
    let loaded = loaded_graph(&ent);
    if !p.admin {
        let mut conn = pool.acquire().await.map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
        if !can(&mut conn, p, res, Target::Stored(id), Perm::Update)
            .await
            .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        {
            return Err(StatusCode::NOT_FOUND);
        }
    }
    apply_ent(&mut ent, object(&v).map_err(|_| StatusCode::NOT_FOUND)?).map_err(|_| StatusCode::NOT_FOUND)?;
    let mut tx = pool.begin().await.map_err(|_| StatusCode::NOT_FOUND)?;
    let writer = Writer { pool, loaded };
    writer.save_ent(&mut tx, &mut ent).await.map_err(|_| StatusCode::NOT_FOUND)?;
    tx.commit().await.map_err(|_| StatusCode::NOT_FOUND)?;
    Ok(ent.to_json(false))
}

// ---------------------------------------------------------------- delete

pub async fn delete_h(st: St, Path((res, id)): Path<(String, String)>, headers: HeaderMap) -> Response {
    let res = match resource(&res) {
        Ok(r) => r,
        Err(s) => return status_only(s),
    };
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    match delete_impl(&st.pool, &p, res, id).await {
        Ok(()) => status_only(StatusCode::NO_CONTENT),
        Err(_) => status_only(StatusCode::NOT_FOUND),
    }
}

async fn delete_impl(pool: &PgPool, p: &Principal, res: Res, id: i32) -> Result<(), ()> {
    let ent = read_one(pool, p, res, id).await.map_err(|_| ())?.ok_or(())?;
    {
        let mut conn = pool.acquire().await.map_err(|_| ())?;
        if !can(&mut conn, p, res, Target::Stored(id), Perm::Delete).await.map_err(|_| ())? {
            return Err(());
        }
    }
    let mut tx = pool.begin().await.map_err(|_| ())?;
    let writer = Writer { pool, loaded: Loaded::default() };
    writer.delete_ent(&mut tx, &ent).await.map_err(|_| ())?;
    tx.commit().await.map_err(|_| ())?;
    Ok(())
}

// ---------------------------------------------------------------- relations

/// `GET /users/{id}/userGroups`: the user's groups the principal may read.
pub async fn user_groups_h(st: St, Path((res, id)): Path<(String, String)>, headers: HeaderMap) -> Response {
    if res != "users" {
        return status_only(StatusCode::NOT_FOUND);
    }
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    match related(&st.pool, &p, Res::Users, id).await {
        Ok(v) => json_response(StatusCode::OK, &v),
        Err(_) => status_only(StatusCode::NOT_FOUND),
    }
}

/// `GET /groups/{id}/users`: the group's members the principal may read.
pub async fn group_users_h(st: St, Path((res, id)): Path<(String, String)>, headers: HeaderMap) -> Response {
    if res != "groups" {
        return status_only(StatusCode::NOT_FOUND);
    }
    let p = match authenticate(&st.pool, &headers).await {
        Ok(p) => p,
        Err(f) => return status_only(f.status()),
    };
    let id = match parse_id(&id) {
        Ok(i) => i,
        Err(s) => return status_only(s),
    };
    match related(&st.pool, &p, Res::Groups, id).await {
        Ok(v) => json_response(StatusCode::OK, &v),
        Err(_) => status_only(StatusCode::NOT_FOUND),
    }
}

/// `getGroupsOfUser` / `getUsersOfGroup`: the owner is looked up without a
/// permission check, the result is filtered by READ.
async fn related(pool: &PgPool, p: &Principal, owner: Res, id: i32) -> Result<Value, ()> {
    let mut conn = pool.acquire().await.map_err(|_| ())?;
    let mut out: Vec<Value> = Vec::new();
    match owner {
        Res::Users => {
            let user = load_user(&mut conn, id).await.map_err(|_| ())?.ok_or(())?;
            for gid in user.user_groups.unwrap_or_default() {
                if let Some(g) = load_group(&mut conn, gid).await.map_err(|_| ())? {
                    if readable(&mut conn, p, Res::Groups, gid).await? {
                        out.push(UserGroup::to_json(&g));
                    }
                }
            }
        }
        Res::Groups => {
            let group = load_group(&mut conn, id).await.map_err(|_| ())?.ok_or(())?;
            for m in group.members.unwrap_or_default() {
                let mid = m.id.ok_or(())?;
                if readable(&mut conn, p, Res::Users, mid).await? {
                    out.push(m.to_json(false));
                }
            }
        }
        _ => return Err(()),
    }
    let _: DbResult<()> = Ok(());
    Ok(Value::Array(out))
}

async fn readable(conn: &mut sqlx::PgConnection, p: &Principal, res: Res, id: i32) -> Result<bool, ()> {
    if p.admin {
        return Ok(true);
    }
    can(conn, p, res, Target::Stored(id), Perm::Read).await.map_err(|_| ())
}

