//! SHOGun REST slice: the `/rest` endpoints of `users`, `groups`, `roles`,
//! `layers`, `layerdatasources` and `layerappearances`, on the schema the
//! original Hibernate application creates.

mod api;
mod auth;
mod db;
mod javaish;
mod model;
mod parse;
mod perm;
mod write;

use std::sync::Arc;
use std::time::Duration;

use axum::routing::get;
use axum::Router;
use sqlx::postgres::PgPoolOptions;

use api::AppState;

fn router(state: Arc<AppState>) -> Router {
    Router::new()
        .route("/rest/:res", get(api::list_h).post(api::create_h))
        .route("/rest/:res/filter", get(api::filter_h))
        .route(
            "/rest/:res/:id",
            get(api::get_h).put(api::update_h).delete(api::delete_h),
        )
        .route("/rest/:res/:id/userGroups", get(api::user_groups_h))
        .route("/rest/:res/:id/users", get(api::group_users_h))
        .with_state(state)
}

#[tokio::main]
async fn main() {
    let database_url = std::env::var("DATABASE_URL").expect("DATABASE_URL must be set");
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(8080);

    let pool = PgPoolOptions::new()
        .max_connections(10)
        .acquire_timeout(Duration::from_secs(30))
        .connect(&database_url)
        .await
        .expect("cannot connect to DATABASE_URL");

    let state = Arc::new(AppState { pool });
    let listener = tokio::net::TcpListener::bind(("0.0.0.0", port))
        .await
        .expect("cannot bind PORT");
    axum::serve(listener, router(state)).await.expect("server error");
}
