//! End-to-end checks through the router against a database with `schema.sql`
//! loaded. They run only when `DATABASE_URL` is set, create their own rows
//! (names starting with `rt`) and remove them again.

use std::sync::Arc;

use axum::body::{to_bytes, Body};
use axum::http::{header, Request, StatusCode};
use axum::Router;
use base64::Engine;
use serde_json::{json, Value};
use sqlx::{PgPool, Row};
use tower::ServiceExt;

use crate::api::AppState;

async fn connect() -> Option<PgPool> {
    let url = std::env::var("DATABASE_URL").ok()?;
    sqlx::postgres::PgPoolOptions::new()
        .max_connections(5)
        .connect(&url)
        .await
        .ok()
}

async fn send(app: &Router, method: &str, path: &str, auth: Option<(&str, &str)>, body: Option<Value>) -> (StatusCode, Value) {
    let mut req = Request::builder().method(method).uri(path);
    if let Some((u, p)) = auth {
        let tok = base64::engine::general_purpose::STANDARD.encode(format!("{}:{}", u, p));
        req = req.header(header::AUTHORIZATION, format!("Basic {}", tok));
    }
    let body = match body {
        Some(v) => {
            req = req.header(header::CONTENT_TYPE, "application/json");
            Body::from(v.to_string())
        }
        None => Body::empty(),
    };
    let resp = app.clone().oneshot(req.body(body).unwrap()).await.unwrap();
    let status = resp.status();
    let bytes = to_bytes(resp.into_body(), 1 << 20).await.unwrap();
    let value = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, value)
}

async fn role_id(pool: &PgPool, name: &str) -> i32 {
    if let Some(r) = sqlx::query("SELECT id FROM roles WHERE name = $1").bind(name).fetch_optional(pool).await.unwrap() {
        return r.get("id");
    }
    sqlx::query("INSERT INTO hibernate_sequences (sequence_name, next_val) VALUES ('default', 0) ON CONFLICT DO NOTHING")
        .execute(pool)
        .await
        .unwrap();
    let id: i64 = sqlx::query_scalar("UPDATE hibernate_sequences SET next_val = next_val + 1 WHERE sequence_name = 'default' RETURNING next_val")
        .fetch_one(pool)
        .await
        .unwrap();
    sqlx::query("INSERT INTO roles (id, created, modified, name) VALUES ($1, now(), now(), $2)")
        .bind(id as i32)
        .bind(name)
        .execute(pool)
        .await
        .unwrap();
    id as i32
}

async fn add_user(pool: &PgPool, id: i32, name: &str, active: bool, roles: &[i32]) {
    let hash = bcrypt::hash("pw", 4).unwrap();
    sqlx::query("INSERT INTO persons (id, created, modified, firstname) VALUES ($1, now(), now(), $2)")
        .bind(id)
        .bind(name)
        .execute(pool)
        .await
        .unwrap();
    sqlx::query("INSERT INTO users (id, accountname, active, password) VALUES ($1, $2, $3, $4)")
        .bind(id)
        .bind(name)
        .bind(active)
        .bind(hash)
        .execute(pool)
        .await
        .unwrap();
    for r in roles {
        sqlx::query("INSERT INTO users_roles (user_id, role_id) VALUES ($1, $2)")
            .bind(id)
            .bind(r)
            .execute(pool)
            .await
            .unwrap();
    }
}

async fn cleanup(pool: &PgPool) {
    let stmts = [
        "DELETE FROM userpermissions WHERE entity_id IN (SELECT id FROM layers WHERE name LIKE 'rt%') OR userpermissions_key IN (SELECT id FROM users WHERE accountname LIKE 'rt%')",
        "DELETE FROM layers WHERE name LIKE 'rt%'",
        "DELETE FROM layerappearances_properties WHERE appearance_id IN (SELECT id FROM layerappearances WHERE name LIKE 'rt%')",
        "DELETE FROM layerappearances WHERE name LIKE 'rt%'",
        "DELETE FROM layerdatasources WHERE name LIKE 'rt%' AND id NOT IN (SELECT source_id FROM layers WHERE source_id IS NOT NULL)",
        "DELETE FROM user_usergroup WHERE user_id IN (SELECT id FROM users WHERE accountname LIKE 'rt%') OR usergroup_id IN (SELECT id FROM usergroups WHERE name LIKE 'rt%')",
        "DELETE FROM usergroups_roles WHERE usergroup_id IN (SELECT id FROM usergroups WHERE name LIKE 'rt%')",
        "DELETE FROM usergroups WHERE name LIKE 'rt%'",
        "DELETE FROM users_roles WHERE user_id IN (SELECT id FROM users WHERE accountname LIKE 'rt%')",
        "DELETE FROM users WHERE accountname LIKE 'rt%'",
        "DELETE FROM persons WHERE firstname LIKE 'rt%' AND id NOT IN (SELECT id FROM users)",
        "DELETE FROM roles WHERE name LIKE 'rt%' AND id NOT IN (SELECT role_id FROM users_roles) AND id NOT IN (SELECT role_id FROM usergroups_roles)",
    ];
    for s in stmts {
        let _ = sqlx::query(s).execute(pool).await;
    }
}

#[tokio::test]
async fn database_flows() {
    let Some(pool) = connect().await else {
        eprintln!("DATABASE_URL not set or unreachable: skipping database tests");
        return;
    };
    cleanup(&pool).await;
    let app = crate::router(Arc::new(AppState { pool: pool.clone() }));

    let role_user = role_id(&pool, "ROLE_USER").await;
    let role_admin = role_id(&pool, "ROLE_ADMIN").await;
    let role_foo = role_id(&pool, "rt_ROLE_FOO").await;
    let base = 900_000;
    add_user(&pool, base, "rt_admin", true, &[role_admin]).await;
    add_user(&pool, base + 1, "rt_user", true, &[role_user]).await;
    add_user(&pool, base + 2, "rt_off", false, &[role_user]).await;
    add_user(&pool, base + 3, "rt_none", true, &[]).await;
    add_user(&pool, base + 4, "rt_foo", true, &[role_foo]).await;
    let admin = ("rt_admin", "pw");
    let user = ("rt_user", "pw");

    // ---- login and roles
    assert_eq!(send(&app, "GET", "/rest/roles", None, None).await.0, StatusCode::UNAUTHORIZED);
    assert_eq!(send(&app, "GET", "/rest/roles", Some(("rt_user", "bad")), None).await.0, StatusCode::UNAUTHORIZED);
    assert_eq!(send(&app, "GET", "/rest/roles", Some(("rt_off", "pw")), None).await.0, StatusCode::UNAUTHORIZED);
    assert_eq!(send(&app, "GET", "/rest/roles", Some(("rt_none", "pw")), None).await.0, StatusCode::UNAUTHORIZED);
    assert_eq!(send(&app, "GET", "/rest/roles", Some(("rt_foo", "pw")), None).await.0, StatusCode::FORBIDDEN);
    assert_eq!(send(&app, "GET", "/rest/roles", Some(user), None).await.0, StatusCode::OK);
    assert_eq!(send(&app, "GET", "/rest/roles", Some(admin), None).await.0, StatusCode::OK);

    // ---- roles: create, read, update, delete
    let (st, created) = send(&app, "POST", "/rest/roles", Some(admin), Some(json!({"name": "rt_role", "description": "d"}))).await;
    assert_eq!(st, StatusCode::CREATED);
    let rid = created["id"].as_i64().unwrap();
    assert_eq!(created, json!({"id": rid, "name": "rt_role", "description": "d"}));
    assert_eq!(send(&app, "POST", "/rest/roles", Some(user), Some(json!({"name": "rt_x"}))).await.0, StatusCode::BAD_REQUEST);
    let (st, got) = send(&app, "GET", &format!("/rest/roles/{}", rid), Some(user), None).await;
    assert_eq!((st, got["name"].clone()), (StatusCode::OK, json!("rt_role")));
    let (st, upd) = send(&app, "PUT", &format!("/rest/roles/{}", rid), Some(admin), Some(json!({"id": rid, "description": "e"}))).await;
    assert_eq!((st, upd["description"].clone()), (StatusCode::OK, json!("e")));
    assert_eq!(send(&app, "PUT", &format!("/rest/roles/{}", rid), Some(admin), Some(json!({"id": rid + 1}))).await.0, StatusCode::BAD_REQUEST);
    let (st, list) = send(&app, "GET", "/rest/roles/filter?name=rt_role&output:only=name", Some(user), None).await;
    assert_eq!(st, StatusCode::OK);
    assert_eq!(list, json!([{"id": null, "name": "rt_role", "description": null}]));
    assert_eq!(send(&app, "DELETE", &format!("/rest/roles/{}", rid), Some(admin), None).await.0, StatusCode::NO_CONTENT);
    assert_eq!(send(&app, "GET", &format!("/rest/roles/{}", rid), Some(admin), None).await.0, StatusCode::NOT_FOUND);
    // a role in use cannot be deleted
    assert_eq!(send(&app, "DELETE", &format!("/rest/roles/{}", role_user), Some(admin), None).await.0, StatusCode::NOT_FOUND);

    // ---- users and groups
    let (st, u) = send(&app, "POST", "/rest/users", Some(admin), Some(json!({"accountName": "rt_new", "password": "plain", "firstName": "New", "roles": [{"id": role_user}]}))).await;
    assert_eq!(st, StatusCode::CREATED);
    let new_id = u["id"].as_i64().unwrap();
    let stored: String = sqlx::query_scalar("SELECT password FROM users WHERE id = $1").bind(new_id as i32).fetch_one(&pool).await.unwrap();
    assert_eq!(stored, "plain", "passwords created through the API are stored as sent");
    assert_eq!(send(&app, "GET", "/rest/roles", Some(("rt_new", "plain")), None).await.0, StatusCode::UNAUTHORIZED);
    let (st, g) = send(&app, "POST", "/rest/groups", Some(admin), Some(json!({"name": "rt_grp", "members": [{"id": base + 1}]}))).await;
    assert_eq!(st, StatusCode::CREATED);
    let gid = g["id"].as_i64().unwrap();
    let (st, members) = send(&app, "GET", &format!("/rest/groups/{}/users", gid), Some(user), None).await;
    assert_eq!(st, StatusCode::OK);
    assert_eq!(members.as_array().map(|a| a.len()), Some(1));
    assert_eq!(send(&app, "GET", &format!("/rest/groups/{}", gid), Some(user), None).await.0, StatusCode::OK);
    assert_eq!(send(&app, "GET", &format!("/rest/groups/{}", gid), Some(("rt_none", "pw")), None).await.0, StatusCode::UNAUTHORIZED);
    let (st, gs) = send(&app, "GET", &format!("/rest/users/{}/userGroups", base + 1), Some(user), None).await;
    assert_eq!((st, gs.as_array().map(|a| a.len())), (StatusCode::OK, Some(1)));
    assert_eq!(send(&app, "DELETE", &format!("/rest/groups/{}", gid), Some(admin), None).await.0, StatusCode::NO_CONTENT);

    // ---- layers, appearances and permissions
    let (st, l) = send(&app, "POST", "/rest/layers", Some(admin), Some(json!({"name": "rt_layer", "appearance": {"name": "rt_app", "properties": {"k": 1, "t": true}}}))).await;
    assert_eq!(st, StatusCode::CREATED);
    let lid = l["id"].as_i64().unwrap();
    assert!(l["appearance"]["id"].as_i64().is_some());
    let props: i64 = sqlx::query_scalar("SELECT count(*) FROM layerappearances_properties WHERE appearance_id = $1")
        .bind(l["appearance"]["id"].as_i64().unwrap() as i32)
        .fetch_one(&pool)
        .await
        .unwrap();
    assert_eq!(props, 2);
    assert_eq!(send(&app, "GET", &format!("/rest/layers/{}", lid), Some(user), None).await.0, StatusCode::NOT_FOUND);
    sqlx::query("INSERT INTO userpermissions (entity_id, userpermissions_key, userpermissions_id) VALUES ($1, $2, $3)")
        .bind(lid as i32)
        .bind(base + 1)
        .bind(permission_collection(&pool, "READ").await)
        .execute(&pool)
        .await
        .unwrap();
    assert_eq!(send(&app, "GET", &format!("/rest/layers/{}", lid), Some(user), None).await.0, StatusCode::OK);
    assert_eq!(send(&app, "PUT", &format!("/rest/layers/{}", lid), Some(user), Some(json!({"id": lid, "name": "rt_x"}))).await.0, StatusCode::NOT_FOUND);
    let (st, p) = send(&app, "GET", "/rest/layerappearances?output:only=name", Some(user), None).await;
    assert_eq!(st, StatusCode::OK);
    assert!(p.as_array().map(|a| a.iter().any(|x| x["name"] == json!("rt_app"))).unwrap_or(false));
    assert_eq!(send(&app, "DELETE", &format!("/rest/layers/{}", lid), Some(admin), None).await.0, StatusCode::NO_CONTENT);

    // ---- data sources: updates only, subtype fields
    let ds = 900_100;
    sqlx::query("INSERT INTO layerdatasources (id, created, modified, name, type, url) VALUES ($1, now(), now(), 'rt_ds', 'ImageWMS', 'http://x/')")
        .bind(ds)
        .execute(&pool)
        .await
        .unwrap();
    sqlx::query("INSERT INTO imagewmslayerdatasources (id, height, width, layernames) VALUES ($1, 10, 20, 'a')")
        .bind(ds)
        .execute(&pool)
        .await
        .unwrap();
    assert_eq!(send(&app, "POST", "/rest/layerdatasources", Some(admin), Some(json!({"name": "rt_no"}))).await.0, StatusCode::BAD_REQUEST);
    let (st, d) = send(&app, "GET", &format!("/rest/layerdatasources/{}", ds), Some(admin), None).await;
    assert_eq!((st, d["width"].clone(), d["height"].clone()), (StatusCode::OK, json!(20), json!(10)));
    let (st, d) = send(&app, "PUT", &format!("/rest/layerdatasources/{}", ds), Some(admin), Some(json!({"id": ds, "width": 30, "name": "rt_ds2"}))).await;
    assert_eq!((st, d["width"].clone(), d["name"].clone()), (StatusCode::OK, json!(30), json!("rt_ds2")));
    assert_eq!(send(&app, "PUT", &format!("/rest/layerdatasources/{}", ds), Some(admin), Some(json!({"id": ds, "tileGrid": null}))).await.0, StatusCode::NOT_FOUND);
    assert_eq!(send(&app, "GET", "/rest/layerdatasources?output:only=name", Some(admin), None).await.0, StatusCode::INTERNAL_SERVER_ERROR);

    // ---- cleanup
    sqlx::query("DELETE FROM imagewmslayerdatasources WHERE id = $1").bind(ds).execute(&pool).await.unwrap();
    sqlx::query("DELETE FROM layerdatasources WHERE id = $1").bind(ds).execute(&pool).await.unwrap();
    sqlx::query("DELETE FROM userpermissions WHERE userpermissions_key = $1").bind(base + 1).execute(&pool).await.unwrap();
    cleanup(&pool).await;
    sqlx::query("DELETE FROM users_roles WHERE user_id IN (SELECT id FROM users WHERE accountname = 'rt_new')").execute(&pool).await.unwrap();
    sqlx::query("DELETE FROM users WHERE accountname = 'rt_new'").execute(&pool).await.unwrap();
    sqlx::query("DELETE FROM persons WHERE id = $1").bind(new_id as i32).execute(&pool).await.unwrap();
    cleanup(&pool).await;
}

async fn permission_collection(pool: &PgPool, perm: &str) -> i32 {
    let id: i64 = sqlx::query_scalar("UPDATE hibernate_sequences SET next_val = next_val + 1 WHERE sequence_name = 'default' RETURNING next_val")
        .fetch_one(pool)
        .await
        .unwrap();
    sqlx::query("INSERT INTO permissioncollections (id, created, modified) VALUES ($1, now(), now())")
        .bind(id as i32)
        .execute(pool)
        .await
        .unwrap();
    sqlx::query("INSERT INTO permissioncollections_permissions (permissioncollections_id, permissions) VALUES ($1, $2)")
        .bind(id as i32)
        .bind(perm)
        .execute(pool)
        .await
        .unwrap();
    id as i32
}

